const $=s=>document.querySelector(s);
function dateText(v,opts={}){if(!v)return '-';const d=new Date(v);if(Number.isNaN(d.getTime()))return String(v);const tz=state?.settings?.timezone||'Asia/Riyadh';const parts=new Intl.DateTimeFormat('ar-SA',{timeZone:tz,day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:true,...opts}).formatToParts(d);const get=k=>parts.find(x=>x.type===k)?.value||'';return `${get('day')}/${get('month')}/${get('year')} — ${get('hour')}:${get('minute')} ${get('dayPeriod')}`;}
function dateOnly(v){return dateText(v,{hour:undefined,minute:undefined,hour12:undefined});}
const state={me:null,cats:[],yards:[],settings:null,tab:'home',owners:[],customerPreview:false};
const OFFLINE_CACHE_KEY='houshakOfflineCacheV1', OFFLINE_QUEUE_KEY='houshakOfflineIntakeV1', OFFLINE_ADMIN_AUTH_KEY='houshakAdminOfflineAuthV1';
function offlineCache(){try{return JSON.parse(localStorage.getItem(OFFLINE_CACHE_KEY)||'{}')}catch{return {}}}
function setOfflineCache(k,v){try{const c=offlineCache();c[k]=v;localStorage.setItem(OFFLINE_CACHE_KEY,JSON.stringify(c))}catch{}}
function isNetworkError(e){return /Failed to fetch|NetworkError|Load failed|offline|fetch/i.test(String(e?.message||e))||!navigator.onLine}
async function offlineDb(){return await new Promise((resolve,reject)=>{const r=indexedDB.open('houshakOfflineDB',1);r.onupgradeneeded=()=>r.result.createObjectStore('intake',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function queueIntake(item){try{const dbx=await offlineDb();await new Promise((res,rej)=>{const tx=dbx.transaction('intake','readwrite');tx.objectStore('intake').put(item);tx.oncomplete=res;tx.onerror=()=>rej(tx.error)});return}catch{}try{const q=JSON.parse(localStorage.getItem(OFFLINE_QUEUE_KEY)||'[]');q.push(item);localStorage.setItem(OFFLINE_QUEUE_KEY,JSON.stringify(q))}catch{} }
async function readQueued(){try{const dbx=await offlineDb();return await new Promise((res,rej)=>{const tx=dbx.transaction('intake','readonly');const r=tx.objectStore('intake').getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)})}catch{try{return JSON.parse(localStorage.getItem(OFFLINE_QUEUE_KEY)||'[]')}catch{return []}}}
async function removeQueued(id){try{const dbx=await offlineDb();await new Promise((res,rej)=>{const tx=dbx.transaction('intake','readwrite');tx.objectStore('intake').delete(id);tx.oncomplete=res;tx.onerror=()=>rej(tx.error)});}catch{}try{const q=JSON.parse(localStorage.getItem(OFFLINE_QUEUE_KEY)||'[]').filter(x=>x.id!==id);localStorage.setItem(OFFLINE_QUEUE_KEY,JSON.stringify(q))}catch{}}
async function syncOfflineIntake(){if(!navigator.onLine)return;const q=await readQueued();for(const item of q){try{await api('/api/admin/offline/intake',{method:'POST',body:JSON.stringify(item)});await removeQueued(item.id)}catch(e){if(isNetworkError(e))break;console.error('offline sync item failed',e);break}}}
window.addEventListener('online',()=>{syncOfflineIntake().then(()=>{if(location.pathname.startsWith('/admin')&&state.me)dashboard(state.tab||'overview',true).catch(()=>{})})});window.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&navigator.onLine)syncOfflineIntake().catch(()=>{})});setInterval(()=>{if(navigator.onLine)syncOfflineIntake().catch(()=>{})},15000);
const roleLabel=role=>({ADMIN:'مدير النظام',MANAGER:'مدير الحوش',YARD:'موظف الحوش',RECEPTION:'موظف الاستقبال',SALES:'المبيعات',ACCOUNTING:'المحاسبة',CUSTOMER:'عميل',SYSTEM:'النظام'})[role]||role||'غير محدد';
function currentUserBadge(){const u=state.me;return `<span class="current-user-badge" aria-label="المستخدم الحالي"><span class="current-user-dot"></span><span><strong>${esc(u?.name||'زائر')}</strong><small>${esc(u?roleLabel(u.role):'غير مسجل الدخول')}</small></span></span>`}
function showActorToast(){if(!location.pathname.startsWith('/admin')||!state.me)return;let el=document.getElementById('actorActionToast');if(!el){el=document.createElement('div');el.id='actorActionToast';el.className='actor-action-toast';el.setAttribute('role','status');el.setAttribute('aria-live','polite');document.body.appendChild(el)}el.textContent=`تم تنفيذ العملية بواسطة ${state.me.name} — ${roleLabel(state.me.role)}`;el.classList.add('visible');clearTimeout(window.__actorToastTimer);window.__actorToastTimer=setTimeout(()=>el.classList.remove('visible'),3600)}
const __apiInFlight=new Map(),__apiRecent=new Map();
async function api(url,opt={}){const method=String(opt.method||'GET').toUpperCase();const body=opt.body||'';const key=(method==='POST'||method==='PUT'||method==='PATCH')?`${method} ${url} ${body}`:null;if(key){const existing=__apiInFlight.get(key)||__apiRecent.get(key);if(existing)return existing;const run=(async()=>{const r=await fetch(url,{cache:method==='GET'?'no-store':undefined,headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.error||'حدث خطأ');if(url.startsWith('/api/admin/')&&['POST','PUT','PATCH','DELETE'].includes(method))showActorToast();return d})();__apiInFlight.set(key,run);const cleanup=()=>{__apiInFlight.delete(key);__apiRecent.set(key,run);setTimeout(()=>{if(__apiRecent.get(key)===run)__apiRecent.delete(key)},2000)};run.then(cleanup,cleanup);return run}try{const r=await fetch(url,{cache:method==='GET'?'no-store':undefined,headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.error||'حدث خطأ');if(method==='GET'&&!url.includes('/api/auth/')){if(url.includes('/api/admin/')){try{sessionStorage.setItem('houshakAdminGET:'+url,JSON.stringify(d))}catch{}try{setOfflineCache('ADMIN_GET '+url,d)}catch{}}else setOfflineCache('GET '+url,d)}if(url.startsWith('/api/admin/')&&['POST','PUT','PATCH','DELETE'].includes(method))showActorToast();return d}catch(e){if(method==='GET'){if(url.includes('/api/admin/')){try{const c=sessionStorage.getItem('houshakAdminGET:'+url);if(c)return JSON.parse(c)}catch{}try{const c=offlineCache()['ADMIN_GET '+url];if(c!==undefined)return c}catch{}}else{const c=offlineCache()['GET '+url];if(c!==undefined)return c}}throw e}}
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const fmt=n=>Number(n||0).toLocaleString('ar-SA');
const purposeName=p=>({STORAGE:'توقيف',SALE:'بيع',RENT:'إيجار',SALE_RENT:'بيع وإيجار'})[p]||p;
const statusName=s=>({ACTIVE:'نشط',RESERVED:'محجوز',SOLD:'مباع',RENTED:'مؤجر',EXITED:'خارج الحوش'})[s]||s;
const identityName=s=>({NATIONAL_ID:'هوية وطنية',PERSONAL_ID:'بطاقة شخصية',RESIDENCY_ID:'هوية مقيم',PASSPORT:'جواز سفر',OTHER:'هوية أخرى'})[s]||s;
const actionName=s=>({CREATE:'إنشاء',UPDATE:'تعديل',DELETE:'حذف',CONFIRM:'تأكيد',CANCEL:'إلغاء',PAYMENT:'تسجيل دفعة',RESERVE:'حجز',EXIT:'إخراج',REJECT:'رفض',ACCEPT:'قبول'})[s]||s;
const entityName=s=>({ASSET:'أصل',OWNER:'مالك',USER:'مستخدم',RESERVATION:'حجز',OFFER:'عرض',ORDER:'طلب',TRANSACTION:'حركة مالية',INVOICE:'فاتورة',CONTRACT:'عقد',LOCATION:'موقع داخل الحوش',CONDITION:'محضر استلام/تسليم',CATEGORY:'تصنيف',VEHICLE_TYPE:'نوع مركبة',INQUIRY:'استفسار',RECEIPT:'سند',SETTINGS:'إعدادات النظام'})[s]||s;
const statusArabic=s=>({PENDING:'قيد المراجعة',CONFIRMED:'مؤكد',REJECTED:'مرفوض',CANCELLED:'ملغى',COMPLETED:'مكتمل',ACCEPTED:'مقبول',NEW:'جديد',IN_PROGRESS:'قيد التنفيذ',DRAFT:'مسودة',APPROVED:'معتمد',ISSUED:'صادرة',PAID:'مدفوعة',REFUNDED:'مستردة بالكامل',PARTIAL:'مدفوعة جزئيًا',RETURNED:'تم الإرجاع',ACTIVE:'نشط',RENTED:'مؤجر'})[s]||s;
function auditDetails(d){if(!d||typeof d!=='object')return '';const labels={status:'الحالة',depositAmount:'العربون',agreedAmount:'المبلغ المتفق عليه',amount:'المبلغ',type:'النوع',assetId:'الأصل',partyName:'الطرف',partyPhone:'الجوال',commissionType:'نوع العمولة',commissionRate:'نسبة العمولة',commissionFixed:'العمولة الثابتة',condition:'حالة الأصل',odometer:'عداد الكيلومترات',engineHours:'ساعات التشغيل',notes:'الملاحظات',description:'البيان',category:'التصنيف',reference:'المرجع'};return Object.entries(d).map(([k,v])=>{if(v===null||v===undefined||v==='')return '';let val=v;if(k==='status'||k==='type')val=statusArabic(v)||v;return `<div><b>${esc(labels[k]||k)}</b>: ${esc(String(val))}</div>`}).filter(Boolean).join('')}
function money(n){return `${fmt(n)} ${esc(state.settings?.currencySymbol||'ر.س')}`}
function waNumber(){let n=String(state.settings?.whatsapp||'').replace(/\D/g,'');if(n.startsWith('00'))n=n.slice(2);if(n.startsWith('0'))n=String(state.settings?.countryCode||'966')+n.slice(1);return n}
let deferredInstallPrompt=null; window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;setTimeout(showInstallPrompt,900)}); window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;document.querySelector('.install-prompt')?.remove()}); function showInstallPrompt(){if(!deferredInstallPrompt||window.matchMedia('(display-mode: standalone)').matches||document.querySelector('.install-prompt'))return;const admin=location.pathname.startsWith('/admin');const name=admin?'حوشك إدارة':'حوشك';const el=document.createElement('div');el.className='install-prompt';el.innerHTML=`<div><strong>ثبّت ${name}</strong><small>أضف المنصة إلى شاشة هاتفك لتفتح مثل التطبيق.</small></div><button class="btn primary" onclick="installHoushak()">تثبيت</button><button class="install-close" onclick="this.parentElement.remove()" aria-label="إغلاق">×</button>`;document.body.appendChild(el)} async function installHoushak(){if(!deferredInstallPrompt)return;deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;document.querySelector('.install-prompt')?.remove()}
async function init(){const adminPath=location.pathname.startsWith('/admin');if(adminPath){try{state.me=(await api('/api/auth/me')).user;try{localStorage.setItem('houshakAdminLastUser',JSON.stringify(state.me))}catch{}}catch{if(!navigator.onLine){try{state.me=JSON.parse(localStorage.getItem('houshakAdminLastUser')||'null')}catch{state.me=null}}else state.me=null}}else{try{state.me=(await api('/api/auth/me')).user;try{localStorage.setItem('houshakLastUser',JSON.stringify(state.me))}catch{}}catch{try{state.me=JSON.parse(localStorage.getItem('houshakLastUser')||'null')}catch{state.me=null}}}if(adminPath&&!navigator.onLine){const c=offlineCache();state.cats=Array.isArray(c.categories)?c.categories:[];state.yards=Array.isArray(c.yards)?c.yards:[];state.settings=c.settings||{name:'حوشك',currency:'SAR',timezone:'Asia/Riyadh'};document.title=`${state.settings.name||'حوشك'} إدارة`;state.customerPreview=false;history.replaceState({view:'exit-guard',admin:true},'',location.pathname+location.search);history.pushState({view:'admin-home'},'',location.pathname+location.search);window.__adminHomeBoundary=true;await adminPortal();return}state.cats=await api('/api/categories');state.yards=await api('/api/yards');state.settings=await api('/api/public/settings');setOfflineCache('categories',state.cats);setOfflineCache('yards',state.yards);setOfflineCache('settings',state.settings);try{setOfflineCache('owners',await api('/api/admin/owners?q='));setOfflineCache('vehicleTypes',await api('/api/vehicle-types'))}catch{}const admin=location.pathname.startsWith('/admin');document.title=admin?`${state.settings.name} إدارة`:state.settings.name;state.customerPreview=new URLSearchParams(location.search).get('customerPreview')==='1';if(admin){history.replaceState({view:'exit-guard',admin:true},'',location.pathname+location.search);history.pushState({view:'admin-home'},'',location.pathname+location.search);window.__adminHomeBoundary=true;await adminPortal();syncOfflineIntake().catch(()=>{});return}history.replaceState({view:'exit-guard',admin:false},'',location.pathname+location.search);history.pushState({view:'home',customerPreview:state.customerPreview},'',location.pathname+location.search);await home(true);startCustomerAutoRefresh();syncOfflineIntake().catch(()=>{})}
function navigate(view,href){history.pushState(view,'',href||location.pathname);return view}
function adminHome(){window.__adminHomeBoundary=true;history.pushState({view:'admin-home'},'',location.pathname+location.search);return dashboard('overview',true)}
function clearAdminSession(){state.me=null;try{localStorage.removeItem('houshakAuth');localStorage.removeItem('houshakLastUser');localStorage.removeItem('houshakAdminLastUser');localStorage.removeItem(OFFLINE_ADMIN_AUTH_KEY);sessionStorage.clear()}catch{}document.body.classList.remove('admin-mode')}
async function exitAdminApp(){if(!confirm('هل أنت متأكد من الخروج من التطبيق؟'))return;clearAdminSession();if(navigator.onLine){try{await api('/api/auth/logout',{method:'POST'})}catch{}}window.__allowExit=true;window.__adminHomeBoundary=false;location.replace('/admin')}
function goBackToPublic(purpose='',cat=''){if(state.customerPreview){returnToAdminPreview();return}if(history.state?.view==='listings'&&history.length>2){history.back();return}if(history.state?.view==='listings'&&history.state.filters){return listings(purpose||history.state.purpose||'',cat||history.state.cat||'',true,history.state.filters)}return home()}
function goBack(){if(document.querySelector('.modal')){closeModal();return}if(location.pathname.startsWith('/admin')){if(window.__adminHomeBoundary||history.state?.view==='admin-home'){return exitAdminApp()}if(history.state?.view&&history.state.view!=='home'){history.back();return}return exitAdminApp()}if(history.state?.view&&history.state.view!=='home'){history.back();return}if(confirm('هل أنت متأكد من الخروج؟')){window.__allowExit=true;history.back()}}
window.addEventListener('popstate',async e=>{if(state.customerPreview&&!location.pathname.startsWith('/admin')){window.__returningFromCustomerPreview=true;location.replace('/admin');return}if(document.querySelector('.modal')){closeModal();history.pushState(e.state||{view:'home'},'',location.href);return}if(location.pathname.startsWith('/admin')&&window.__adminHomeBoundary&&!window.__allowExit){history.pushState({view:'admin-home'},'',location.pathname+location.search);return exitAdminApp()}const s=e.state;try{if(s?.view==='detail'&&s.id)return detail(s.id,true);if(s?.view==='about')return aboutPage(true);if(s?.view==='listings')return listings(s.purpose||'',s.cat||'',true,s.filters||{});if(s?.view==='favorites')return clientFavorites(true);if(s?.view==='dashboard')return dashboard(s.tab||'overview',true);if(s?.view==='home')return home(true);if(s?.view==='admin-home'){window.__adminHomeBoundary=true;return dashboard('overview',true)}if(s?.view==='exit-guard'||!s){if(confirm('هل أنت متأكد من الخروج من التطبيق؟')){window.__allowExit=true;history.back()}else{window.__allowExit=false;if(s?.admin){window.__adminHomeBoundary=true;history.pushState({view:'admin-home'},'',location.pathname+location.search);return dashboard('overview',true)}history.pushState({view:'home',customerPreview:state.customerPreview},'',location.pathname+location.search)}}}catch(err){console.error(err);home(true)}})
function tickerHtml(s){const xs=Array.isArray(s.tickerMessages)?s.tickerMessages.filter(Boolean):[];return xs.length?`<section class="ticker" aria-label="رسائل حوشك"><div class="ticker-track">${xs.map((x,i)=>`<span class="ticker-item">${i?'• ':''}${esc(x)}</span>`).join('')}</div></section>`:''}
function locationButton(s){const lat=String(s?.latitude||'').trim(),lng=String(s?.longitude||'').trim(),url=String(s?.mapsUrl||'').trim();const q=lat&&lng?encodeURIComponent(`${lat},${lng}`):encodeURIComponent(s?.address||[s?.country,s?.city].filter(Boolean).join('، ')||'حوشك');const href=url||`https://www.google.com/maps/search/?api=1&query=${q}`;return `<div class="location-cta"><span>📍 ${esc(s?.address||'موقع الحوش')}</span><a class="btn" target="_blank" rel="noopener noreferrer" href="${esc(href)}">الوصول إلى موقع الحوش</a></div>`}
function shell(content){const s=state.settings||{name:'النظام'};const previewBar=state.customerPreview?`<div class="customer-preview-bar"><span>أنت الآن في معاينة العميل — هذه الواجهة للعرض فقط.</span><button class="btn primary" onclick="returnToAdminPreview()">العودة إلى لوحة الإدارة</button></div>`:'';return `${previewBar}<header class="top"><div class="nav"><div><div class="brand">${esc(s.name)}</div><small>${esc(s.tagline||'')}</small></div><div class="navlinks"><button onclick="home()">الرئيسية</button><button onclick="listings('SALE')">للبيع</button><button onclick="listings('RENT')">للإيجار</button><button onclick="listings()">المعروض</button><button onclick="clientFavorites()">المفضلة</button></div>${currentUserBadge()}</div></header>${tickerHtml(s)}${content}<footer class="footer"><div><strong>${esc(s.name)}</strong> — ${esc(s.tagline||'منصة إدارة وعرض ووساطة المركبات والمعدات والأصول')}</div><div class="footer-credit">مالك الحوش: ${esc(s.ownerName||'أبو مناحي السبيعي')}${s.ownerPhone?` · ${esc(s.ownerPhone)}`:''} · مدير الحوش: ${esc(s.managerName||'أبو أنس الإدريسي')}${s.managerPhone?` · ${esc(s.managerPhone)}`:''} · تطوير وبرمجة: ${esc(s.developerName||'هيثم القاضي')} · © ${new Date().getFullYear()} ${esc(s.name)} — جميع الحقوق محفوظة</div></footer>`}
function adminShell(content){const s=state.settings||{name:'النظام'};return `<header class="top admin-top"><div class="nav"><div><div class="brand">${esc(s.name)} — الإدارة</div><small>لوحة التحكم الداخلية</small></div>${currentUserBadge()}<div class="navlinks"><button onclick="adminHome()">الرئيسية</button><button onclick="customerPreview()">👁️ معاينة كعميل</button><button onclick="home()">المنصة العامة</button><button onclick="logout()">خروج</button></div></div></header>${content}<footer class="footer">${esc(s.name)} — لوحة الإدارة الداخلية</footer>`}
async function adminPortal(){document.body.classList.add('admin-mode');if(!state.me){return adminLogin()}if(!['ADMIN','MANAGER','SALES','ACCOUNTING','RECEPTION'].includes(state.me.role)){await api('/api/auth/logout',{method:'POST'}).catch(()=>{});state.me=null;return adminLogin('لا تملك صلاحية الدخول إلى لوحة الإدارة')}if(!navigator.onLine)return offlineAdminHome();try{await dashboard('overview',true)}catch(e){if(/تسجيل الدخول مطلوب|401/i.test(String(e?.message||e))){state.me=null;return adminLogin()}throw e}}
function offlineAdminHome(){state.tab='assets';const name=state.settings?.name||'حوشك';document.querySelector('#app').innerHTML=adminShell(`<main class="container"><div class="panel"><div class="section-head"><div><h2>لوحة الإدارة — ${esc(name)}</h2><p class="muted">أنت الآن تعمل بدون إنترنت. يمكنك إدخال الأصول الجديدة، وسيتم إرسالها تلقائيًا عند عودة الاتصال.</p></div><span class="badge">بدون إنترنت</span></div><div class="toolbar"><button class="btn primary btn-add-asset" onclick="assetForm()">＋ إضافة أصل جديد</button></div></div><div class="panel"><h3>المزامنة المعلقة</h3><p class="muted">الأصول التي تحفظها أثناء الانقطاع تبقى على هذا الجهاز حتى تعود الشبكة، ثم تتم مزامنتها تلقائيًا. لا يتم تعديل الأصول الموجودة على الخادم أثناء وضع عدم الاتصال.</p></div></main>`)}
function customerPreview(){location.href='/?customerPreview=1'}
function returnToAdminPreview(){if(!state.customerPreview)return;window.__returningFromCustomerPreview=true;location.replace('/admin')}
async function offlineCredentialHash(value){const data=new TextEncoder().encode(String(value||''));const digest=await crypto.subtle.digest('SHA-256',data);return Array.from(new Uint8Array(digest)).map(x=>x.toString(16).padStart(2,'0')).join('')}
async function rememberAdminOfflineAuth(user,username,password){try{const credentialHash=await offlineCredentialHash(`${username}\x00${password}`);localStorage.setItem(OFFLINE_ADMIN_AUTH_KEY,JSON.stringify({user,username,credentialHash,savedAt:new Date().toISOString()}))}catch{}}
async function readAdminOfflineAuth(username,password){try{const x=JSON.parse(localStorage.getItem(OFFLINE_ADMIN_AUTH_KEY)||'null');if(!x||!x.user||!x.credentialHash)return null;const credentialHash=await offlineCredentialHash(`${username}\x00${password}`);return x.credentialHash===credentialHash?x.user:null}catch{return null}}
function adminLogin(error=''){document.body.classList.add('admin-mode');const root=document.querySelector('#app');if(!root)return;root.innerHTML=`<div class="admin-login-wrap"><section class="panel admin-login"><div class="brand admin-login-brand">${esc(state.settings?.name||'حوشك')} — الإدارة</div><p class="muted">تسجيل دخول إدارة الحوش</p>${error?`<div class="notice danger">${esc(error)}</div>`:''}<div class="field"><label for="lp">اسم المستخدم / الجوال</label><input id="lp" class="input" type="text" inputmode="tel" autocomplete="username" placeholder="أدخل اسم المستخدم أو الجوال"></div><div class="field"><label for="lx">كلمة المرور</label><input id="lx" class="input" type="password" autocomplete="current-password" placeholder="أدخل كلمة المرور"></div><button class="btn primary" onclick="adminLoginSubmit()">دخول لوحة الإدارة</button><button class="btn" onclick="location.href='/'">العودة للمنصة</button></section></div>`}
async function adminLoginSubmit(){const username=$('#lp').value.trim(),password=$('#lx').value;try{const login=await api('/api/auth/login',{method:'POST',body:JSON.stringify({phone:username,password})});state.me=login.user||(await api('/api/auth/me')).user;try{localStorage.setItem('houshakAdminLastUser',JSON.stringify(state.me))}catch{}await rememberAdminOfflineAuth(state.me,username,password);location.href='/admin'}catch(e){if(isNetworkError(e)||!navigator.onLine){const cached=await readAdminOfflineAuth(username,password);if(cached&&['ADMIN','MANAGER','SALES','ACCOUNTING','RECEPTION'].includes(cached.role)){state.me=cached;try{localStorage.setItem('houshakAdminLastUser',JSON.stringify(cached))}catch{}location.href='/admin';return}return adminLogin('لا يوجد اتصال بالإنترنت. لتسجيل الدخول دون اتصال، يجب أن تكون قد سجلت دخولك بنجاح إلى هذه الإدارة مرة واحدة أثناء وجود الإنترنت على هذا الجهاز.')}adminLogin(e.message)}}
async function aboutPage(fromHistory=false){const s=state.settings||await api('/api/public/settings');document.querySelector('#app').innerHTML=shell(`<main class="container about-page"><div class="page-head"><button class="btn" onclick="goBack()">← رجوع</button><div><h1>${esc(s.aboutTitle||'عن حوشك')}</h1><p class="muted">تعرف على المنصة والحوش والخدمات وطريقة الاستخدام.</p></div></div><section class="about-hero panel"><div class="about-mark">🏠</div><div><h2>${esc(s.name)}</h2><p>${esc(s.aboutText||'')}</p></div></section><section class="about-grid"><article class="panel"><h3>ماذا نقدم؟</h3><p>${esc(s.servicesText||'')}</p></article><article class="panel"><h3>كيف تستخدم حوشك؟</h3><p>${esc(s.howToText||'')}</p></article><article class="panel"><h3>رؤيتنا والتطوير المستمر</h3><p>${esc(s.futureText||'')}</p></article><article class="panel"><h3>عن الحوش</h3><p>مالك الحوش: <strong>${esc(s.ownerName||'أبو مناحي السبيعي')}</strong>${s.ownerPhone?` — ${esc(s.ownerPhone)}`:''}</p><p>مدير الحوش: <strong>${esc(s.managerName||'أبو أنس الإدريسي')}</strong>${s.managerPhone?` — ${esc(s.managerPhone)}`:''}</p><p class="muted">يمكنك الاستفسار عن أي أصل أو خدمة من صفحة التفاصيل أو عبر وسائل التواصل المتاحة في المنصة.</p></article></section><section class="panel location-panel"><h3>📍 موقع الحوش</h3><p>${esc(s.address||'يمكنك فتح موقع الحوش مباشرة على الخريطة.')}</p>${locationButton(s)}</section><section class="panel contact-panel"><h3>هل لديك استفسار؟</h3><p>ما عليك إلا اختيار الأصل أو الخدمة ثم إرسال استفسارك من خلال صفحة التفاصيل، أو استخدام وسيلة التواصل المتاحة في المنصة.</p>${s.whatsapp?`<a class="btn success" target="_blank" rel="noopener" href="https://wa.me/${esc(waNumber())}">التواصل عبر واتساب</a>`:''}</section></main>`);if(!fromHistory)navigate({view:'about'},'#about')}
const CLIENT_FAVORITES_KEY='houshakClientFavoritesV1';
function readClientFavorites(){try{const x=JSON.parse(localStorage.getItem(CLIENT_FAVORITES_KEY)||'[]');return Array.isArray(x)?x.filter(v=>typeof v==='string'):[]}catch{return []}}
function isClientFavorite(id){return readClientFavorites().includes(String(id))}
function toggleClientFavorite(event,id){event?.stopPropagation?.();const xs=readClientFavorites();const next=xs.includes(String(id))?xs.filter(x=>x!==String(id)):[...xs,String(id)];try{localStorage.setItem(CLIENT_FAVORITES_KEY,JSON.stringify(next))}catch{}const btn=event?.currentTarget;if(btn){const active=next.includes(String(id));btn.classList.toggle('is-favorite',active);btn.setAttribute('aria-pressed',String(active));btn.setAttribute('aria-label',active?'إزالة من المفضلة':'إضافة إلى المفضلة');btn.textContent=btn.classList.contains('favorite-detail')?(active?'♥ محفوظ في المفضلة':'♡ أضف للمفضلة'):(active?'♥':'♡')}if(document.querySelector('#favoriteResults'))clientFavorites(true)}
function clientPrice(a,purpose=''){if(purpose==='RENT')return a.rentPrice==null?null:Number(a.rentPrice);if(a.salePriceMode==='ON_BID'||a.salePrice==null)return null;return Number(a.salePrice)}
function sortClientListings(xs,sort='newest',purpose=''){const out=[...xs];if(sort==='price-asc'||sort==='price-desc'){out.sort((a,b)=>{const ap=clientPrice(a,purpose),bp=clientPrice(b,purpose);if(ap===null&&bp===null)return new Date(b.createdAt||0)-new Date(a.createdAt||0);if(ap===null)return 1;if(bp===null)return -1;return sort==='price-asc'?ap-bp:bp-ap})}else if(sort==='oldest')out.sort((a,b)=>new Date(a.createdAt||0)-new Date(b.createdAt||0));else out.sort((a,b)=>new Date(b.createdAt||0)-new Date(a.createdAt||0));return out}
function temporaryOffersSection(all){const offers=(all||[]).filter(a=>a.temporaryOffer&&a.temporaryOffer.endsAt&&new Date(a.temporaryOffer.endsAt).getTime()>Date.now()).sort((a,b)=>new Date(a.temporaryOffer.endsAt)-new Date(b.temporaryOffer.endsAt)).slice(0,8);if(!offers.length)return '';return `<section class="panel client-section client-temporary-offers-section"><div class="section-head"><div><h2>🏷️ عروض لفترة محدودة</h2><p class="muted">اغتنم العرض قبل انتهاء مدته.</p></div><span class="temporary-offer-section-count">${offers.length} ${offers.length===1?'عرض':'عروض'}</span></div>${cards(offers,true)}</section>`}
async function home(fromHistory=false){let all=[];try{all=await api('/api/listings?limit=200')}catch(e){all=[]}const ordered=sortClientListings(all,'newest').slice(0,12),featured=ordered.slice(0,8);const categories=state.cats||[];document.querySelector('#app').innerHTML=shell(`<main class="container client-home client-home-redesigned"><section class="hero client-home-hero"><div class="client-hero-copy"><span class="client-eyebrow">حوش أبو مناحي</span><h1>أحدث المعروض</h1><p>تعرّف على أحدث المركبات والمعدات المتاحة، وافتح الإعلان لمعرفة التفاصيل.</p></div><form class="client-home-search" onsubmit="event.preventDefault();homeSearch()"><label for="homeSearchQuery">ابحث عن مركبة أو معدة</label><div class="client-search-row"><input id="homeSearchQuery" class="input" type="search" placeholder="مثال: دينا، قلاب، سطحة، شاحنة" autocomplete="off"><button class="btn primary" type="submit">بحث</button></div><div class="client-quick-links"><button type="button" class="client-chip" onclick="listings('SALE')">للبيع</button><button type="button" class="client-chip" onclick="listings('RENT')">للإيجار</button><button type="button" class="client-chip" onclick="clientFavorites()">♡ المفضلة</button></div></form></section>${temporaryOffersSection(all)}<section class="panel client-section client-latest-section"><div class="section-head"><div><h2>أحدث المعروض</h2><p class="muted">تُعرض الإعلانات الأحدث أولًا.</p></div><button class="btn" onclick="listings()">عرض جميع المعروض</button></div>${`<div id="clientLatestCards">${cards(featured,true)}</div>`}<p class="client-auto-refresh-note" id="clientAutoRefreshNote" aria-live="polite">يتحدث المعروض تلقائيًا عند إضافة إعلانات جديدة.</p></section><section class="panel client-section client-category-section"><div class="section-head"><div><h2>تصفّح حسب النوع</h2><p class="muted">اختر نوع المركبة أو المعدة مباشرة.</p></div></div>${categories.length?`<div class="client-category-rail" aria-label="تصنيفات المعروض">${categories.map(c=>`<button class="client-category-chip" onclick="listings('',${JSON.stringify(c.id)})"><span>${esc(c.icon||'📦')}</span><strong>${esc(c.name)}</strong></button>`).join('')}</div>`:'<div class="empty">لا توجد تصنيفات متاحة حاليًا.</div>'}</section><section class="panel client-contact-cta client-track-cta"><div><h2>تابع طلبك</h2><p>تابع الاستفسارات والحجوزات وعروض الشراء باستخدام رمز المتابعة ورقم الجوال.</p></div><button class="btn primary" onclick="openRequestTracker()">متابعة طلباتي</button></section><section class="panel client-contact-cta"><div><h2>تحتاج إلى مساعدة؟</h2><p>تواصل مع إدارة الحوش لمعرفة المزيد عن أحد الإعلانات.</p></div><button class="btn primary" onclick="aboutPage()">عن الحوش وطرق التواصل</button></section></main>`);__customerListingSignature=listingSignature(all);if(!fromHistory)navigate({view:'home'},'#home')}
let __customerRefreshTimer=null,__customerRefreshBusy=false,__customerListingSignature='',__customerDetailSignature='';
function startCustomerAutoRefresh(){if(location.pathname.startsWith('/admin'))return;if(__customerRefreshTimer)clearInterval(__customerRefreshTimer);__customerRefreshTimer=setInterval(()=>{if(document.visibilityState==='visible'&&navigator.onLine)refreshCustomerListings().catch(()=>{})},10000);window.addEventListener('focus',()=>{if(navigator.onLine)refreshCustomerListings().catch(()=>{})},{passive:true});}
function listingSignature(xs){return JSON.stringify((xs||[]).map(a=>[a.id,a.updatedAt||a.createdAt,a.status,a.publicVisible,a.title,a.description,a.purpose,a.category?.id,a.category?.name,a.model,a.color,a.variant,a.salePriceMode,a.salePrice,a.rentPrice,a.rentUnit,a.currentBid,a.temporaryOffer,a.yard?.city,(a.images||[]).map(i=>[i.id,i.url,i.sortOrder,i.createdAt])]))}
function clientAssetSignature(a){return JSON.stringify([a?.id,a?.updatedAt||a?.createdAt,a?.status,a?.publicVisible,a?.title,a?.description,a?.purpose,a?.category?.id,a?.category?.name,a?.model,a?.color,a?.variant,a?.salePriceMode,a?.salePrice,a?.rentPrice,a?.rentUnit,a?.currentBid,a?.yard?.city,(a?.images||[]).map(i=>[i.id,i.url,i.sortOrder,i.createdAt])])}
async function refreshCustomerListings(){if(__customerRefreshBusy||!navigator.onLine||location.pathname.startsWith('/admin'))return;const view=history.state?.view||'home';if(!['home','listings','favorites','detail'].includes(view))return;__customerRefreshBusy=true;try{const all=await api('/api/listings?limit=200');const sig=listingSignature(all);const changed=sig!==__customerListingSignature;__customerListingSignature=sig;if(view==='detail'){const id=history.state?.id;if(!id)return;try{const fresh=await api('/api/listings/'+encodeURIComponent(id));const freshSig=clientAssetSignature(fresh);if(freshSig!==__customerDetailSignature&&!document.querySelector('.modal')){const scrollY=window.scrollY;await detail(id,true);__customerDetailSignature=freshSig;window.scrollTo({top:scrollY,behavior:'instant'});const note=document.querySelector('#clientDetailAutoRefreshNote');if(note)note.textContent='تم تحديث بيانات الإعلان تلقائيًا'}}catch(e){if(e.status===404){const app=document.querySelector('#app');if(app)app.innerHTML=shell('<main class="container"><section class="panel"><div class="notice">هذا الإعلان لم يعد متاحًا للعرض، ربما تم حجز الأصل أو بيعه أو إخفاؤه من الإدارة.</div><button class="btn primary" onclick="home()">العودة إلى أحدث المعروض</button></section></main>');history.replaceState({view:'home'},'', '#home')}}return}if(!changed)return;if(view==='home'){const offersSection=document.querySelector('.client-temporary-offers-section');const offersMarkup=temporaryOffersSection(all);if(offersSection){if(offersMarkup)offersSection.outerHTML=offersMarkup;else offersSection.remove()}else if(offersMarkup){const latestSection=document.querySelector('.client-latest-section');if(latestSection)latestSection.insertAdjacentHTML('beforebegin',offersMarkup)}const latest=document.querySelector('#clientLatestCards');if(latest)latest.innerHTML=cards(sortClientListings(all,'newest').slice(0,8),true);const note=document.querySelector('#clientAutoRefreshNote');if(note)note.textContent='تم تحديث المعروض تلقائيًا · '+new Date().toLocaleTimeString('ar',{hour:'2-digit',minute:'2-digit'});try{const cats=await api('/api/categories');if(JSON.stringify(cats)!==JSON.stringify(state.cats)){state.cats=cats;const rail=document.querySelector('.client-category-rail');if(rail)rail.innerHTML=cats.map(c=>`<button class="client-category-chip" onclick="listings('',${JSON.stringify(c.id)})"><span>${esc(c.icon||'📦')}</span><strong>${esc(c.name)}</strong></button>`).join('')}}catch{}}else if(view==='listings'){const f=window.__clientListingContext||{};const xs=await fetchClientListingResults(f);const results=document.querySelector('#results');if(results)results.innerHTML=cards(xs,true);const count=document.querySelector('#clientResultCount');if(count)count.textContent=`${xs.length} نتيجة`;const note=document.querySelector('#clientListingAutoRefreshNote');if(note)note.textContent='تم تحديث النتائج تلقائيًا'}else if(view==='favorites'){await clientFavorites(true)}}catch(e){/* Keep the current view available if connectivity is interrupted. */}finally{__customerRefreshBusy=false}}
function homeSearch(){const q=$('#homeSearchQuery')?.value?.trim()||'';listings('', '', false,{q})}
async function listings(purpose='',cat='',fromBack=false,initialFilters={}){const category=state.cats.find(c=>c.id===cat);const title=category?.name||(purpose==='SALE'?'المعروض للبيع':purpose==='RENT'?'المعروض للإيجار':'كل المعروض');const filters={q:initialFilters.q||'',categoryId:cat||'',purpose:purpose||'',min:initialFilters.min||'',max:initialFilters.max||'',sort:initialFilters.sort||'newest'};window.__clientListingContext=filters;let xs=[];try{xs=await fetchClientListingResults(filters)}catch(e){document.querySelector('#app').innerHTML=shell(`<main class="container"><div class="notice danger">تعذر تحميل المعروض. تحقق من اتصالك ثم أعد المحاولة.</div><button class="btn" onclick="listings('${esc(purpose)}','${esc(cat)}')">إعادة المحاولة</button></main>`);return}document.querySelector('#app').innerHTML=shell(`<main class="container client-listings"><div class="page-head"><button class="btn" onclick="goBackToPublic('${esc(purpose)}','${esc(cat)}')">← رجوع</button><div><h1>${esc(title)}</h1><p class="muted">ابحث وقارن الخيارات المتاحة، ثم افتح التفاصيل قبل اتخاذ القرار.</p></div></div><section class="panel client-filter-panel"><form class="client-filter-form" onsubmit="event.preventDefault();applyClientListingFilters()"><div class="client-filter-query"><label for="q">بحث</label><input id="q" class="input" type="search" value="${esc(filters.q)}" placeholder="الاسم أو الكود أو الموديل أو الموقع"></div><div><label for="purposeFilter">الغرض</label><select id="purposeFilter" class="select"><option value="" ${!purpose?'selected':''}>بيع وإيجار</option><option value="SALE" ${purpose==='SALE'?'selected':''}>للبيع</option><option value="RENT" ${purpose==='RENT'?'selected':''}>للإيجار</option></select></div><div><label for="cat">التصنيف</label><select id="cat" class="select"><option value="">كل التصنيفات</option>${state.cats.map(c=>`<option value="${esc(c.id)}" ${filters.categoryId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div><label for="min">أقل سعر</label><input id="min" class="input" type="number" min="0" inputmode="decimal" value="${esc(filters.min)}" placeholder="من"></div><div><label for="max">أعلى سعر</label><input id="max" class="input" type="number" min="0" inputmode="decimal" value="${esc(filters.max)}" placeholder="إلى"></div><div><label for="clientSort">ترتيب النتائج</label><select id="clientSort" class="select"><option value="newest" ${filters.sort==='newest'?'selected':''}>الأحدث أولًا</option><option value="price-asc" ${filters.sort==='price-asc'?'selected':''}>السعر: الأقل أولًا</option><option value="price-desc" ${filters.sort==='price-desc'?'selected':''}>السعر: الأعلى أولًا</option><option value="oldest" ${filters.sort==='oldest'?'selected':''}>الأقدم أولًا</option></select></div><div class="client-filter-actions"><button class="btn primary" type="submit">تطبيق البحث</button><button class="btn" type="button" onclick="clearClientListingFilters()">مسح الفلاتر</button></div></form></section><div class="client-results-head"><strong id="clientResultCount">${xs.length} نتيجة</strong><button class="btn" onclick="clientFavorites()">♡ المفضلة</button></div><p id="clientListingAutoRefreshNote" class="client-auto-refresh-note" aria-live="polite">تُحدّث النتائج تلقائيًا عند إضافة أو تعديل المعروض.</p><div id="results">${cards(xs,true)}</div></main>`);if(!fromBack)navigate({view:'listings',purpose,cat,filters},`#listings${cat?'-'+cat:''}${purpose?'-'+purpose.toLowerCase():''}`)}
async function fetchClientListingResults(filters={}){const qs=new URLSearchParams();if(filters.purpose)qs.set('purpose',filters.purpose);if(filters.categoryId)qs.set('categoryId',filters.categoryId);if(filters.q)qs.set('q',filters.q);if(filters.min)qs.set('minPrice',filters.min);if(filters.max)qs.set('maxPrice',filters.max);qs.set('limit','200');const xs=await api('/api/listings?'+qs);return sortClientListings(xs,filters.sort||'newest',filters.purpose||'')}
async function applyClientListingFilters(){const purpose=$('#purposeFilter')?.value||'',categoryId=$('#cat')?.value||'',q=$('#q')?.value?.trim()||'',min=$('#min')?.value||'',max=$('#max')?.value||'',sort=$('#clientSort')?.value||'newest';if(min&&Number(min)<0||max&&Number(max)<0){alert('السعر لا يمكن أن يكون سالبًا.');return}if(min&&max&&Number(min)>Number(max)){alert('الحد الأدنى للسعر يجب ألا يتجاوز الحد الأعلى.');return}await listings(purpose,categoryId,false,{q,min,max,sort})}
async function clearClientListingFilters(){await listings()}
function cards(xs,market=false){return xs.length?`<div class="${market?'market-grid':'grid'}">${xs.map(a=>`<article class="card market-card"><div class="image-wrap gallery-cover" onclick="detail('${esc(a.id)}')">${a.images?.[0]?`<img loading="lazy" decoding="async" src="${esc(a.images[0].url)}" alt="${esc(a.title)}" onerror="this.style.display='none';this.parentElement.querySelector('.image-placeholder-fallback').style.display='grid'">`:`<div class="image-placeholder">${esc(a.category?.icon||'📦')}</div>`}<div class="image-placeholder image-placeholder-fallback" style="display:none">${esc(a.category?.icon||'📦')}</div>${a.images?.length?`<span class="image-count">📷 ${a.images.length} صورة</span>`:''}<span class="offer-badge">${purposeName(a.purpose)}</span><button type="button" class="favorite-toggle ${isClientFavorite(a.id)?'is-favorite':''}" aria-label="${isClientFavorite(a.id)?'إزالة من المفضلة':'إضافة إلى المفضلة'}" aria-pressed="${isClientFavorite(a.id)}" onclick="toggleClientFavorite(event,'${esc(a.id)}')">${isClientFavorite(a.id)?'♥':'♡'}</button></div><div class="body"><h3 title="${esc(a.title)}">${esc(a.title)}</h3><p class="muted market-card-subtitle">${esc([a.model,a.color].filter(Boolean).join(' · ')||'التفاصيل والصور في الإعلان')}</p>${a.salePriceMode==='ON_BID'?`<div class="price">على السوم</div>`:a.salePrice!=null?`<div class="price">${purposeName(a.purpose)==='إيجار'?'':'السعر المطلوب: '}${money(a.salePrice)}</div>`:''}${a.currentBid?`<div class="price">السوم الحالي: ${money(a.currentBid)}</div>`:''}${a.rentPrice?`<div class="price">${money(a.rentPrice)} / ${esc(a.rentUnit||'يوم')}</div>`:''}<p class="muted">${esc(a.category?.name||'')} ${a.yard?.city?`· ${esc(a.yard.city)}`:''}</p><button class="btn primary card-detail-btn" onclick="detail('${esc(a.id)}')">عرض التفاصيل</button></div></article>`).join('')}</div>`:'<div class="empty client-empty"><span>🔎</span><strong>لا توجد نتائج مطابقة</strong><p>جرّب تغيير كلمات البحث أو مسح بعض الفلاتر.</p></div>'}
async function doSearch(purpose){const c=window.__clientListingContext||{};await listings(purpose||c.purpose||'',$('#cat')?.value||c.categoryId||'',false,{q:$('#q')?.value||'',min:$('#min')?.value||'',max:$('#max')?.value||'',sort:$('#clientSort')?.value||'newest'})}
async function clientFavorites(refresh=false){const ids=readClientFavorites();let all=[];try{all=await api('/api/listings?limit=200')}catch{}const xs=sortClientListings(all.filter(a=>ids.includes(String(a.id))),'newest');document.querySelector('#app').innerHTML=shell(`<main class="container client-listings"><div class="page-head"><button class="btn" onclick="goBack()">← رجوع</button><div><h1>المفضلة</h1><p class="muted">الأصول التي حفظتها على هذا الجهاز.</p></div></div><div class="client-results-head"><strong>${xs.length} أصل محفوظ</strong><button class="btn" onclick="listings()">تصفح المعروض</button></div><div id="favoriteResults">${cards(xs,true)}</div>${!xs.length?'<div class="notice">لم تحفظ أي أصل بعد. اضغط على رمز ♡ في بطاقة الأصل لإضافته إلى المفضلة.</div>':''}</main>`);if(!refresh)navigate({view:'favorites'},'#favorites')}

async function openImageGallery(id,index=0){try{const a=await api('/api/listings/'+id);const imgs=a.images||[];if(!imgs.length)return;const i=Math.max(0,Math.min(Number(index)||0,imgs.length-1));window.__gallery={id,index:i,images:imgs,title:a.title};const img=imgs[i];modal(`<div class="lightbox"><div class="lightbox-head"><strong>${esc(a.title)}</strong><span>${i+1} / ${imgs.length}</span></div><img class="lightbox-image" src="${img.url}" alt="${esc(a.title)} — صورة ${i+1}"><div class="lightbox-actions"><button class="btn" onclick="galleryMove('${a.id}',${i-1})" ${i===0?'disabled':''}>→ السابقة</button><button class="btn primary" onclick="closeModal()">إغلاق</button><button class="btn" onclick="galleryMove('${a.id}',${i+1})" ${i===imgs.length-1?'disabled':''}>التالية ←</button></div></div>`)}catch(e){alert(e.message)}}
async function galleryMove(id,index){const g=window.__gallery;if(!g||g.id!==id)return openImageGallery(id,index);if(index<0||index>=g.images.length)return;g.index=index;const img=g.images[index];modal(`<div class="lightbox"><div class="lightbox-head"><strong>${esc(g.title||state.settings?.name||'حوشك')}</strong><span>${index+1} / ${g.images.length}</span></div><img class="lightbox-image" src="${img.url}" alt="صورة ${index+1}"><div class="lightbox-actions"><button class="btn" onclick="galleryMove('${id}',${index-1})" ${index===0?'disabled':''}>→ السابقة</button><button class="btn primary" onclick="closeModal()">إغلاق</button><button class="btn" onclick="galleryMove('${id}',${index+1})" ${index===g.images.length-1?'disabled':''}>التالية ←</button></div></div>`)}
async function detail(id,fromHistory=false){const a=await api('/api/listings/'+id);let related=[];try{related=(await api('/api/listings?'+new URLSearchParams({categoryId:a.category?.id||'',purpose:a.purpose==='RENT'?'RENT':a.purpose==='SALE'?'SALE':'',limit:'200'}))).filter(x=>x.id!==a.id).slice(0,4)}catch{}const favorite=isClientFavorite(a.id);document.querySelector('#app').innerHTML=shell(`<main class="container client-detail-page"><div class="client-detail-back"><button class="btn" onclick="history.back();setTimeout(()=>{if(!document.querySelector('#results'))home()},50)">← رجوع إلى المعروض</button><span class="muted">كود الأصل: ${esc(a.code||'—')}</span></div><div class="client-detail-layout"><section class="panel client-detail-main">${a.temporaryOffer?`<section class="temporary-offer-banner" aria-label="عرض مؤقت"><div class="temporary-offer-top"><span class="temporary-offer-kicker">🔥 عرض مؤقت</span><span class="temporary-offer-countdown">ينتهي ${esc(new Date(a.temporaryOffer.endsAt).toLocaleString("ar-SA",{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"}))}</span></div><h2>${esc(a.temporaryOffer.title||"عرض لفترة محدودة")}</h2>${a.temporaryOffer.description?`<p>${esc(a.temporaryOffer.description)}</p>`:""}${a.temporaryOffer.price!==null?`<div class="temporary-offer-price">سعر العرض: ${money(a.temporaryOffer.price)}</div>`:""}</section>`:""}<div class="gallery">${(a.images||[]).map((i,n)=>`<button class="gallery-thumb" onclick="openImageGallery('${esc(a.id)}',${n})" type="button" aria-label="تكبير صورة ${n+1} من ${esc(a.title)}"><img loading="lazy" decoding="async" src="${esc(i.url)}" alt="${esc(a.title)} — صورة ${n+1}"><span class="gallery-number">${n+1}</span><span class="gallery-zoom" aria-hidden="true">+</span></button>`).join('')||'<div class="empty">لا توجد صور متاحة لهذا الأصل.</div>'}</div><div class="client-detail-title-row"><div><span class="pill">${purposeName(a.purpose)}</span><h1>${esc(a.title)}</h1></div><button class="btn favorite-detail ${favorite?'is-favorite':''}" type="button" aria-pressed="${favorite}" onclick="toggleClientFavorite(event,'${esc(a.id)}')">${favorite?'♥ محفوظ في المفضلة':'♡ أضف للمفضلة'}</button></div><p class="client-detail-description">${esc(a.description||'لا توجد تفاصيل إضافية مكتوبة لهذا الأصل.')}</p><div class="client-detail-facts"><div><small>التصنيف</small><strong>${esc(a.category?.name||'—')}</strong></div><div><small>الموقع</small><strong>${esc(a.yard?.city||'يرجى التواصل لمعرفة الموقع')}</strong></div><div><small>كود الأصل</small><strong>${esc(a.code||'—')}</strong></div>${a.model?`<div><small>الموديل</small><strong>${esc(a.model)}</strong></div>`:''}${a.color?`<div><small>اللون</small><strong>${esc(a.color)}</strong></div>`:''}${a.variant?`<div><small>تفاصيل إضافية</small><strong>${esc(a.variant)}</strong></div>`:''}</div><section class="client-detail-price-box"><h2>السعر والتوفر</h2>${a.salePriceMode==='ON_BID'?`<div class="price">السعر: على السوم</div>`:a.salePrice!=null?`<div class="price">سعر البيع المطلوب: ${money(a.salePrice)}</div>`:''}${a.currentBid?`<div class="price">السوم الحالي: ${money(a.currentBid)}</div>`:''}${a.rentPrice?`<div class="price">الإيجار: ${money(a.rentPrice)} / ${esc(a.rentUnit||'يوم')}</div>`:''}<p class="muted">التوفر النهائي وشروط البيع أو الإيجار تؤكدها إدارة الحوش عند التواصل.</p><p id="clientDetailAutoRefreshNote" class="client-auto-refresh-note" aria-live="polite">يتم التحقق من تحديث الصور والسعر والتوفر تلقائيًا.</p></section><div class="client-detail-actions"><a class="btn success" target="_blank" rel="noopener noreferrer" href="https://wa.me/${esc(waNumber())}?text=${encodeURIComponent('استفسار عن الإعلان '+(a.code||'')+' - '+a.title)}">التواصل عبر واتساب</a><button class="btn primary" onclick="inquiry('${esc(a.id)}','${esc(a.title)}')">إرسال استفسار</button>${['RENT','SALE','SALE_RENT'].includes(a.purpose)?`<button class="btn" onclick="reserve('${esc(a.id)}')">طلب حجز</button>`:''}${['SALE','SALE_RENT'].includes(a.purpose)?`<button class="btn" onclick="offer('${esc(a.id)}')">تقديم عرض شراء</button>`:''}</div></section><aside class="panel client-detail-aside"><h2>قبل أن تتخذ قرارك</h2><ul><li>راجع الصور والمعلومات المتاحة.</li><li>تحقق من السعر والشروط مع إدارة الحوش.</li><li>لا تعتبر الحجز مؤكدًا حتى تظهر لك رسالة تأكيد صريحة.</li></ul><div class="notice">يمكنك إرسال استفسار إذا احتجت إلى معلومات إضافية عن الأصل.</div><button class="btn" onclick="aboutPage()">معلومات الحوش والتواصل</button></aside></div>${related.length?`<section class="panel client-section"><div class="section-head"><div><h2>أصول مشابهة</h2><p class="muted">خيارات أخرى من التصنيف نفسه.</p></div><button class="btn" onclick="listings('${a.purpose==='RENT'?'RENT':a.purpose==='SALE'?'SALE':''}','${esc(a.category?.id||'')}')">عرض المزيد</button></div>${cards(related,true)}</section>`:''}</main>`);__customerDetailSignature=clientAssetSignature(a);if(!fromHistory)navigate({view:'detail',id},`#detail-${id}`)}
window.__requestTrackerTimer=window.__requestTrackerTimer||null;window.__requestTrackerBusy=window.__requestTrackerBusy||false;function stopRequestTrackerAutoRefresh(){if(window.__requestTrackerTimer){clearInterval(window.__requestTrackerTimer);window.__requestTrackerTimer=null}}function startRequestTrackerAutoRefresh(){stopRequestTrackerAutoRefresh();window.__requestTrackerTimer=setInterval(()=>{if(document.visibilityState==='visible'&&navigator.onLine&&document.querySelector('.modal #trackToken')&&document.querySelector('.modal #trackPhone')&&!window.__requestTrackerBusy)trackRequest(true)},15000)}function modal(html){const m=document.createElement('div');m.className='modal';m.innerHTML=`<div>${html}<div class="toolbar"><button class="btn" onclick="closeModal()">إغلاق</button></div></div>`;document.body.appendChild(m)}function closeModal(){stopRequestTrackerAutoRefresh();document.querySelector('.modal')?.remove()}
function userForm(u={}){if(!state.me||!['ADMIN','MANAGER'].includes(state.me.role)){alert('لا تملك صلاحية إدارة المستخدمين.');return}if(u.id&&state.me.role!=='ADMIN'&&['ADMIN','MANAGER'].includes(u.role)){alert('لا تملك صلاحية تعديل حساب إداري أعلى.');return}const roles=state.me.role==='ADMIN'?[['CUSTOMER','عميل'],['RECEPTION','استقبال'],['SALES','مبيعات'],['YARD','موظف الحوش'],['ACCOUNTING','محاسبة'],['MANAGER','مدير'],['ADMIN','مدير النظام']]:[['CUSTOMER','عميل'],['RECEPTION','استقبال'],['SALES','مبيعات'],['YARD','موظف الحوش'],['ACCOUNTING','محاسبة']];modal(`<h3>${u.id?'تعديل المستخدم':'إضافة مستخدم أو مدير'}</h3><p class="muted">لا يمكن لمدير الحوش إنشاء مدير أو مدير نظام أو تعديل صلاحياتهم.</p><div id="userFormError" class="notice danger" style="display:none"></div><div class="field"><label for="unName">الاسم الكامل *</label><input id="unName" class="input" autocomplete="name" required value="${esc(u.name||'')}"></div><div class="two"><div class="field"><label for="unPhone">رقم الجوال *</label><input id="unPhone" class="input" inputmode="tel" autocomplete="tel" required value="${esc(u.phone||'')}"></div><div class="field"><label for="unRole">الدور والصلاحية *</label><select id="unRole" class="select">${roles.map(r=>`<option value="${r[0]}" ${u.role===r[0]?'selected':''}>${r[1]}</option>`).join('')}</select></div></div><div class="field"><label for="unPassword">${u.id?'كلمة مرور جديدة (اختياري)':'كلمة المرور المؤقتة *'}</label><input id="unPassword" class="input" type="password" autocomplete="new-password" minlength="8" ${u.id?'':'required'}><small class="muted">${u.id?'اترك الحقل فارغًا للإبقاء على كلمة المرور الحالية.':'8 أحرف على الأقل.'}</small></div><div class="two"><div class="field"><label for="unIdentityType">نوع الهوية</label><select id="unIdentityType" class="select">${[['NATIONAL_ID','هوية وطنية'],['PERSONAL_ID','بطاقة شخصية'],['RESIDENCY_ID','هوية مقيم'],['PASSPORT','جواز سفر'],['OTHER','أخرى']].map(r=>`<option value="${r[0]}" ${(u.identityType||'NATIONAL_ID')===r[0]?'selected':''}>${r[1]}</option>`).join('')}</select></div><div class="field"><label for="unIdentityNumber">رقم الهوية</label><input id="unIdentityNumber" class="input" value="${esc(u.identityNumber||'')}"></div></div><div class="two"><div class="field"><label for="unEmail">البريد الإلكتروني (اختياري)</label><input id="unEmail" class="input" type="email" autocomplete="email" value="${esc(u.email||'')}"></div><div class="field"><label for="unAddress">العنوان (اختياري)</label><input id="unAddress" class="input" autocomplete="street-address" value="${esc(u.address||'')}"></div></div><label class="checkline"><input id="unActive" type="checkbox" ${u.active!==false?'checked':''}> المستخدم نشط ويمكنه تسجيل الدخول</label><button id="userSaveBtn" class="btn primary" onclick="saveUser('${u.id||''}')">${u.id?'حفظ التعديلات':'حفظ المستخدم'}</button>`)}
function categoryForm(c={}){if(!state.me||!['ADMIN','MANAGER'].includes(state.me.role)){alert('لا تملك صلاحية إدارة التصنيفات.');return}modal(`<h3>${c.id?'تعديل التصنيف':'إضافة تصنيف جديد'}</h3><div id="categoryFormError" class="notice danger" style="display:none"></div><div class="field"><label for="catName">اسم التصنيف *</label><input id="catName" class="input" maxlength="100" required value="${esc(c.name||'')}" placeholder="مثال: شاحنات"></div><div class="two"><div class="field"><label for="catIcon">الأيقونة</label><input id="catIcon" class="input" maxlength="12" value="${esc(c.icon||'📦')}" placeholder="📦"></div><div class="field"><label for="catSort">ترتيب العرض</label><input id="catSort" class="input" type="number" min="0" step="1" value="${Number.isFinite(Number(c.sortOrder))?Number(c.sortOrder):state.cats.length}"></div></div><div class="field"><label for="catDescription">الوصف (اختياري)</label><textarea id="catDescription" class="input" maxlength="500">${esc(c.description||'')}</textarea></div><div class="field-section"><h4>أغراض التصنيف</h4><label class="checkline"><input id="catSale" type="checkbox" ${c.allowSale!==false?'checked':''}> يسمح بالبيع</label><label class="checkline"><input id="catRent" type="checkbox" ${c.allowRent!==false?'checked':''}> يسمح بالإيجار</label><label class="checkline"><input id="catStorage" type="checkbox" ${c.allowStorage!==false?'checked':''}> يسمح بالتوقيف</label><label class="checkline"><input id="catActive" type="checkbox" ${c.active!==false?'checked':''}> تصنيف نشط ويظهر للعميل</label></div><button id="categorySaveBtn" class="btn primary" onclick="saveCategory('${c.id||''}')">${c.id?'حفظ التعديلات':'إضافة التصنيف'}</button>`)}
function editCategory(id){const c=state.cats.find(x=>x.id===id);if(!c){api('/api/admin/categories').then(xs=>{state.cats=xs;const found=xs.find(x=>x.id===id);if(found)categoryForm(found);else alert('التصنيف غير موجود')}).catch(e=>alert(e.message));return}categoryForm(c)}
async function saveCategory(id){if(window.__categorySaveBusy)return;const name=$('#catName')?.value.trim()||'',err=$('#categoryFormError'),btn=$('#categorySaveBtn');if(!name){if(err){err.textContent='اسم التصنيف مطلوب.';err.style.display='block'}return}window.__categorySaveBusy=true;if(btn){btn.disabled=true;btn.textContent='جارٍ الحفظ…'}try{const payload={name,icon:$('#catIcon')?.value.trim()||'📦',description:$('#catDescription')?.value.trim()||'',sortOrder:Math.max(0,Number($('#catSort')?.value||0)),allowSale:!!$('#catSale')?.checked,allowRent:!!$('#catRent')?.checked,allowStorage:!!$('#catStorage')?.checked,active:!!$('#catActive')?.checked};const saved=await api(id?'/api/admin/categories/'+encodeURIComponent(id):'/api/admin/categories',{method:id?'PUT':'POST',body:JSON.stringify(payload)});closeModal();state.cats=await api('/api/categories');await dashboard('categories');alert(id?'تم تحديث التصنيف بنجاح.':'تمت إضافة التصنيف بنجاح.')}catch(e){if(err){err.textContent=e.message||'تعذر حفظ التصنيف.';err.style.display='block'}else alert(e.message)}finally{window.__categorySaveBusy=false;if(btn){btn.disabled=false;btn.textContent=id?'حفظ التعديلات':'إضافة التصنيف'}}}
function locationForm(l={}){if(!state.me||!['ADMIN','MANAGER','YARD','RECEPTION'].includes(state.me.role)){alert('لا تملك صلاحية إدارة مواقع الحوش.');return}const yards=state.yards||[];modal(`<h3>${l.id?'تعديل موقع الحوش':'إضافة موقع داخل الحوش'}</h3><div id="locationFormError" class="notice danger" style="display:none"></div><div class="field"><label for="locName">اسم الموقع *</label><input id="locName" class="input" maxlength="120" required value="${esc(l.name||'')}" placeholder="مثال: الساحة الشمالية"></div><div class="two"><div class="field"><label for="locCode">رمز الموقع *</label><input id="locCode" class="input" maxlength="40" required value="${esc(l.code||'')}" placeholder="مثال: A-01"></div><div class="field"><label for="locZone">المنطقة / الصف</label><input id="locZone" class="input" maxlength="120" value="${esc(l.zone||'')}" placeholder="مثال: الصف A"></div></div><div class="field"><label for="locYard">الحوش</label><select id="locYard" class="select">${yards.map(y=>`<option value="${esc(y.id)}" ${(l.yardId||yards[0]?.id)===y.id?'selected':''}>${esc(y.name||y.code||'الحوش')}</option>`).join('')}</select><small class="muted">إذا كان لديك حوش واحد، اترك الاختيار الافتراضي.</small></div><label class="checkline"><input id="locActive" type="checkbox" ${l.active!==false?'checked':''}> الموقع نشط</label><button id="locationSaveBtn" class="btn primary" onclick="saveLocation('${l.id||''}')">${l.id?'حفظ التعديلات':'إضافة الموقع'}</button>`)}
async function saveLocation(id){if(window.__locationSaveBusy)return;const name=$('#locName')?.value.trim()||'',code=$('#locCode')?.value.trim()||'',err=$('#locationFormError'),btn=$('#locationSaveBtn');if(!name||!code){if(err){err.textContent='اسم الموقع ورمزه مطلوبان.';err.style.display='block'}return}window.__locationSaveBusy=true;if(btn){btn.disabled=true;btn.textContent='جارٍ الحفظ…'}try{const payload={id,name,code,zone:$('#locZone')?.value.trim()||'',yardId:$('#locYard')?.value||state.yards[0]?.id,active:!!$('#locActive')?.checked};await api(id?'/api/admin/locations':'/api/admin/locations',{method:id?'PUT':'POST',body:JSON.stringify(payload)});closeModal();await dashboard('locations');alert(id?'تم تحديث الموقع بنجاح.':'تمت إضافة الموقع بنجاح.')}catch(e){if(err){err.textContent=e.message||'تعذر حفظ الموقع.';err.style.display='block'}else alert(e.message)}finally{window.__locationSaveBusy=false;if(btn){btn.disabled=false;btn.textContent=id?'حفظ التعديلات':'إضافة الموقع'}}}
async function conditionForm(){if(!state.me||!['ADMIN','MANAGER','RECEPTION','YARD'].includes(state.me.role)){alert('لا تملك صلاحية إنشاء محضر استلام أو تسليم.');return}try{const assets=await api('/api/admin/assets');const available=assets.filter(a=>a.status!=='EXITED');if(!available.length){alert('لا توجد أصول متاحة لإنشاء محضر. أضف أصلًا أولًا.');return}modal(`<h3>إضافة محضر استلام / تسليم</h3><div id="conditionFormError" class="notice danger" style="display:none"></div><div class="field"><label for="condAsset">الأصل *</label><select id="condAsset" class="select" required>${available.map(a=>`<option value="${esc(a.id)}">${esc(a.code||'')} — ${esc(a.title||a.category?.name||'أصل')}</option>`).join('')}</select></div><div class="field"><label for="condType">نوع المحضر *</label><select id="condType" class="select"><option value="ENTRY">استلام / دخول</option><option value="EXIT">تسليم / خروج</option></select></div><div class="two"><div class="field"><label for="condCondition">الحالة الظاهرية</label><select id="condCondition" class="select"><option>جيدة</option><option>جيدة جدًا</option><option>تحتاج إلى ملاحظات</option><option>متضررة</option></select></div><div class="field"><label for="condOdometer">عداد الكيلومترات</label><input id="condOdometer" class="input" type="number" min="0" step="1"></div><div class="field"><label for="condHours">ساعات التشغيل</label><input id="condHours" class="input" type="number" min="0" step="0.1"></div></div><div class="field"><label for="condAccessories">الملحقات</label><textarea id="condAccessories" class="input" maxlength="1000" placeholder="المفاتيح، الإطارات الاحتياطية، الملحقات…"></textarea></div><div class="field"><label for="condNotes">الملاحظات</label><textarea id="condNotes" class="input" maxlength="2000" placeholder="سجل أي ملاحظات على حالة الأصل"></textarea></div><button id="conditionSaveBtn" class="btn primary" onclick="saveCondition()">حفظ المحضر</button>`)}catch(e){alert('تعذر فتح نموذج المحضر: '+(e.message||'خطأ غير معروف'))}}

async function conditionDetails(id){try{const xs=await api('/api/admin/conditions');const c=xs.find(x=>x.id===id);if(!c){alert('المحضر غير موجود.');return}modal(`<h3>تفاصيل محضر الاستلام / التسليم</h3><div class="detail-list"><div><b>الأصل:</b> ${esc(c.asset?.title||'-')} (${esc(c.asset?.code||'-')})</div><div><b>النوع:</b> ${c.type==='ENTRY'?'استلام / دخول':'تسليم / خروج'}</div><div><b>الحالة الظاهرية:</b> ${esc(c.condition||'-')}</div><div><b>عداد الكيلومترات:</b> ${esc(c.odometer||'-')}</div><div><b>ساعات التشغيل:</b> ${esc(c.engineHours||'-')}</div><div><b>الملحقات:</b> ${esc(c.accessories||'-')}</div><div><b>الملاحظات:</b> ${esc(c.notes||'-')}</div><div><b>المسؤول:</b> ${esc(c.user?.name||'-')}</div><div><b>التاريخ:</b> ${esc(dateText(c.createdAt))}</div></div><p class="muted">هذا المحضر سجل توثيقي؛ لا يُعدّل بعد الحفظ حتى لا يتغير سجل حالة الأصل بأثر رجعي.</p><button class="btn primary" onclick="window.print()">طباعة المحضر</button>`)}catch(e){alert('تعذر تحميل تفاصيل المحضر: '+e.message)}}
async function saveCondition(){if(window.__conditionSaveBusy)return;const assetId=$('#condAsset')?.value,type=$('#condType')?.value||'ENTRY',odometer=$('#condOdometer')?.value||'',engineHours=$('#condHours')?.value||'',err=$('#conditionFormError'),btn=$('#conditionSaveBtn');if(!assetId){if(err){err.textContent='اختر الأصل أولًا.';err.style.display='block'}return}if((odometer!==''&&Number(odometer)<0)||(engineHours!==''&&Number(engineHours)<0)){if(err){err.textContent='لا يمكن أن تكون قراءة العداد أو ساعات التشغيل سالبة.';err.style.display='block'}return}window.__conditionSaveBusy=true;if(btn){btn.disabled=true;btn.textContent='جارٍ حفظ المحضر…'}try{await api('/api/admin/conditions',{method:'POST',body:JSON.stringify({assetId,type,odometer,engineHours,condition:$('#condCondition')?.value||'جيدة',accessories:$('#condAccessories')?.value.trim()||'',notes:$('#condNotes')?.value.trim()||''})});closeModal();await dashboard('conditions');alert('تم حفظ محضر الاستلام / التسليم بنجاح.')}catch(e){if(err){err.textContent=e.message||'تعذر حفظ المحضر.';err.style.display='block'}else alert(e.message)}finally{window.__conditionSaveBusy=false;if(btn){btn.disabled=false;btn.textContent='حفظ المحضر'}}}

async function saveUser(id=''){if(window.__userSaveBusy)return;const btn=$('#userSaveBtn'),error=$('#userFormError');const showError=msg=>{if(error){error.textContent=msg;error.style.display='block'}else alert(msg)};const name=$('#unName')?.value.trim()||'',phone=$('#unPhone')?.value.trim()||'',password=$('#unPassword')?.value||'',role=$('#unRole')?.value||'CUSTOMER';if(!name||!phone)return showError('يرجى إدخال الاسم ورقم الجوال.');if(!id&&!password)return showError('كلمة المرور مطلوبة عند إنشاء المستخدم.');if(password&&password.length<8)return showError('كلمة المرور يجب ألا تقل عن 8 أحرف.');if(!/^[-+()\d\s]{6,24}$/.test(phone))return showError('تحقق من رقم الجوال، ويمكن استخدام الأرقام وعلامة + والمسافات.');if(state.me?.role==='MANAGER'&&['ADMIN','MANAGER'].includes(role))return showError('لا تملك صلاحية إنشاء أو تعيين مدير أو مدير نظام.');window.__userSaveBusy=true;if(btn){btn.disabled=true;btn.textContent='جارٍ الحفظ...'}try{const payload={name,phone,role,active:!!$('#unActive')?.checked,identityType:$('#unIdentityType')?.value||'NATIONAL_ID',identityNumber:$('#unIdentityNumber')?.value.trim()||'',email:$('#unEmail')?.value.trim()||'',address:$('#unAddress')?.value.trim()||''};if(password)payload.password=password;await api(id?'/api/admin/users/'+encodeURIComponent(id):'/api/admin/users',{method:id?'PUT':'POST',body:JSON.stringify(payload)});closeModal();await dashboard('users');alert(id?'تم تحديث المستخدم بنجاح.':'تم حفظ المستخدم بنجاح.')}catch(e){showError(e.message||'تعذر حفظ المستخدم. تحقق من البيانات والاتصال ثم حاول مجددًا.')}finally{window.__userSaveBusy=false;if(btn){btn.disabled=false;btn.textContent=id?'حفظ التعديلات':'حفظ المستخدم'}}}
