function inquiry(id,title){window.__inquiryBusy=false;modal(`<h3>استفسار عن ${esc(title)}</h3><p class="muted">أدخل بيانات التواصل ورسالتك، وستتمكن من متابعة الرد برمز المتابعة.</p><div class="field"><label for="inName">الاسم *</label><input id="inName" class="input" required minlength="2" maxlength="120" autocomplete="name" placeholder="الاسم"></div><div class="field"><label for="inPhone">رقم الجوال *</label><input id="inPhone" class="input" type="tel" required minlength="7" maxlength="24" inputmode="tel" autocomplete="tel" placeholder="رقم الجوال المستخدم للتواصل"></div><div class="field"><label for="inMsg">الرسالة *</label><textarea id="inMsg" class="input" required minlength="3" maxlength="2000" placeholder="ما المعلومات التي تحتاجها؟"></textarea></div><p id="inquiryFormError" class="error" role="alert"></p><button id="inquirySubmitBtn" class="btn primary" onclick="sendInquiry('${id}')">إرسال الاستفسار</button>`)}
function trackedRequests(){try{return JSON.parse(localStorage.getItem('houshakTrackedRequests')||'[]')}catch{return []}}function rememberTrackedRequest(r,phone){if(!r?.trackingToken)return;const xs=trackedRequests().filter(x=>x.trackingToken!==r.trackingToken);xs.unshift({trackingToken:r.trackingToken,phone:String(phone||''),code:r.code||'',kind:r.reservationType==='RENT'?'RESERVATION':r.amount?'OFFER':r.message?'INQUIRY':'RESERVATION',createdAt:r.createdAt||new Date().toISOString(),lastSeenUpdatedAt:r.updatedAt||r.createdAt||new Date().toISOString()});try{localStorage.setItem('houshakTrackedRequests',JSON.stringify(xs.slice(0,30)))}catch{}}function showSubmittedRequest(r,message){const code=esc(r.code||'');modal(`<div class="request-success"><h3>✓ ${esc(message)}</h3><p>رقم الطلب: <strong>${code}</strong></p><p class="muted">احتفظ برمز المتابعة الموجود على هذا الجهاز ورقم الجوال لمراجعة الحالة لاحقًا.</p><button class="btn primary" onclick="closeModal();openRequestTracker()">متابعة حالة الطلب</button><button class="btn" onclick="closeModal()">إغلاق</button></div>`)}function openRequestTracker(){const xs=trackedRequests();modal(`<h3>متابعة طلباتي</h3><p class="muted">تُحفظ رموز المتابعة على هذا الجهاز فقط. لا تشاركها مع الآخرين. بعد فتح طلب، تتحدث حالته تلقائيًا كل 15 ثانية ما دامت نافذة المتابعة مفتوحة والاتصال متاحًا.</p>${xs.length?`<div class="tracked-request-list">${xs.map((x,i)=>`<button class="tracked-request" onclick="trackSavedRequest(${i})"><strong>${esc(x.code||'طلب')}</strong><small>${esc(x.phone)} · ${dateText(x.createdAt)}</small><small>اضغط لجلب آخر حالة ورد الإدارة</small></button>`).join('')}</div>`:'<div class="empty">لا توجد طلبات محفوظة على هذا الجهاز بعد.</div>'}<div class="field"><label>رمز المتابعة</label><input id="trackToken" class="input" autocomplete="off" placeholder="الصق رمز المتابعة"></div><div class="field"><label>رقم الجوال المستخدم في الطلب</label><input id="trackPhone" class="input" type="tel" autocomplete="tel" placeholder="رقم الجوال"></div><button class="btn primary" onclick="trackRequest()">عرض الحالة وتحديثها</button><div id="trackResult"></div>`)}async function trackSavedRequest(i){const x=trackedRequests()[i];if(!x)return;$('#trackToken').value=x.trackingToken;$('#trackPhone').value=x.phone;await trackRequest()}async function trackRequest(automatic=false){if(window.__requestTrackerBusy)return;const token=$('#trackToken')?.value?.trim(),phone=$('#trackPhone')?.value?.trim(),box=$('#trackResult');if(!token||!phone){if(box)box.innerHTML='<p class="error">أدخل رمز المتابعة ورقم الجوال.</p>';return}if(box&&!automatic)box.innerHTML='<p class="muted">جارٍ جلب آخر التحديثات…</p>';window.__requestTrackerBusy=true;try{const r=await api(`/api/request-status?token=${encodeURIComponent(token)}&phone=${encodeURIComponent(phone)}`);const labels={INQUIRY:'استفسار',RESERVATION:'طلب حجز',OFFER:'عرض شراء'};const states={OPEN:'تم الاستلام — بانتظار المتابعة',PENDING:'قيد المراجعة',IN_PROGRESS:'قيد المتابعة',CONFIRMED:'مؤكد',REJECTED:'مرفوض',CANCELLED:'ملغى',COMPLETED:'مكتمل',ACCEPTED:'مقبول',CLOSED:'تمت معالجة الطلب'};const saved=trackedRequests();let item=saved.find(x=>x.trackingToken===token);if(!item){item={trackingToken:token,phone,code:r.code||'',kind:r.kind,createdAt:r.createdAt||new Date().toISOString(),lastSeenUpdatedAt:r.createdAt||null};saved.unshift(item)}const previous=item.lastSeenUpdatedAt||item.createdAt||null;const hasUpdate=!!(previous&&r.updatedAt&&new Date(r.updatedAt)>new Date(previous));item.lastSeenUpdatedAt=r.updatedAt||item.lastSeenUpdatedAt;item.code=r.code||item.code;item.kind=r.kind||item.kind;item.phone=phone;try{localStorage.setItem('houshakTrackedRequests',JSON.stringify(saved.slice(0,30)))}catch{}const history=(r.history||[]).slice().sort((a,b)=>new Date(b.at)-new Date(a.at));box.innerHTML=`<div class="request-status-card"><div class="request-status-heading"><h4>${esc(labels[r.kind]||'طلب')} ${esc(r.code||'')}</h4><button class="btn" type="button" onclick="trackRequest()">↻ تحديث</button></div>${hasUpdate?'<p class="request-update-badge" role="status">وصل تحديث جديد على طلبك</p>':''}<p>الأصل: <strong>${esc(r.asset?.title||'غير محدد')}</strong> ${r.asset?.code?`<small>(${esc(r.asset.code)})</small>`:''}</p><p>الحالة الحالية: <strong>${esc(states[r.status]||r.status)}</strong></p><p class="muted">آخر تحديث: ${dateText(r.updatedAt)}</p>${r.amount?`<p>قيمة العرض: <strong>${fmt(r.amount)}</strong></p>`:''}${r.fromAt?`<p>من: ${dateText(r.fromAt)} ${r.toAt?' — إلى: '+dateText(r.toAt):''}</p>`:''}${r.latestReply?`<section class="request-latest-reply"><h5>آخر رد من إدارة الحوش</h5><p>${esc(r.latestReply.body)}</p><small>${dateText(r.latestReply.at)}</small></section>`:''}${r.kind==='INQUIRY'?`<h5>محادثة الاستفسار</h5><div class="request-message-list">${(r.messages||[]).map(m=>`<article class="request-message ${m.sender==='الإدارة'?'from-staff':'from-customer'}"><strong>${esc(m.sender)}</strong><p>${esc(m.body)}</p><small>${dateText(m.at)}</small></article>`).join('')||'<p class="muted">لا توجد رسائل بعد.</p>'}</div>`:''}<h5>التسلسل الزمني للحالة</h5>${history.map(h=>`<div class="status-history-item"><strong>${esc(states[h.status]||h.status)}</strong><small>${dateText(h.at)}</small>${h.note?`<p>${esc(h.note)}</p>`:''}</div>`).join('')||'<p class="muted">لا توجد تحديثات إضافية بعد.</p>'}<p class="muted request-tracker-footnote">تتحدث الحالة تلقائيًا كل 15 ثانية أثناء بقاء نافذة المتابعة مفتوحة؛ ويمكنك الضغط على «تحديث» في أي وقت.</p></div>`;startRequestTrackerAutoRefresh()}catch(e){if(box)box.innerHTML=`<p class="error">${esc(e.message||'تعذر جلب حالة الطلب')}</p>`}finally{window.__requestTrackerBusy=false}}
async function sendInquiry(id){if(window.__inquiryBusy)return;const name=$('#inName')?.value.trim()||'',phone=$('#inPhone')?.value.trim()||'',message=$('#inMsg')?.value.trim()||'',err=$('#inquiryFormError');if(name.length<2||phone.replace(/\D/g,'').length<7||message.length<3){if(err)err.textContent='أكمل الاسم ورقم جوال صحيحًا ورسالة لا تقل عن 3 أحرف.';return}window.__inquiryBusy=true;const btn=$('#inquirySubmitBtn');if(btn){btn.disabled=true;btn.textContent='جارٍ إرسال الاستفسار…'}try{const clientRequestId=window.__inquiryRequestId||(window.__inquiryRequestId=crypto.randomUUID());const r=await api('/api/inquiries',{method:'POST',body:JSON.stringify({assetId:id,name,phone,message,clientRequestId})});window.__inquiryRequestId=null;rememberTrackedRequest(r,phone);closeModal();showSubmittedRequest(r,'تم إرسال الاستفسار بنجاح')}catch(e){window.__inquiryBusy=false;if(btn){btn.disabled=false;btn.textContent='إرسال الاستفسار'}if(err)err.textContent=e.message||'تعذر الإرسال؛ حاول مجددًا.'}}
function reserve(id){window.__reservationBusy=false;modal(`<h3>طلب حجز</h3><p class="muted">هذا طلب مبدئي؛ لا يصبح الحجز مؤكدًا إلا بعد مراجعة الإدارة والاتفاق على الشروط.</p><div class="two"><div class="field"><label for="rn">الاسم *</label><input id="rn" class="input" required minlength=2 autocomplete="name"></div><div class="field"><label for="rp">الجوال *</label><input id="rp" class="input" type="tel" required inputmode="tel" autocomplete="tel"></div></div><div class="two"><div class="field"><label for="rf">من (اختياري)</label><input id="rf" class="input" type="datetime-local"></div><div class="field"><label for="rt">إلى (اختياري)</label><input id="rt" class="input" type="datetime-local"></div></div><p id="reservationFormError" class="error" role="alert"></p><button id="reservationSubmitBtn" class="btn primary" onclick="sendReserve('${id}')">إرسال طلب الحجز</button>`)}
async function sendReserve(id){if(window.__reservationBusy)return;const name=$('#rn')?.value.trim()||'',phone=$('#rp')?.value.trim()||'',from=$('#rf')?.value||'',to=$('#rt')?.value||'',err=$('#reservationFormError');if(name.length<2||phone.replace(/\D/g,'').length<7){if(err)err.textContent='أدخل الاسم ورقم جوال صحيحًا (7 أرقام على الأقل).';return}if(from&&to&&new Date(to)<=new Date(from)){if(err)err.textContent='وقت نهاية الحجز يجب أن يكون بعد وقت البداية.';return}window.__reservationBusy=true;const btn=$('#reservationSubmitBtn');if(btn){btn.disabled=true;btn.textContent='جارٍ إرسال طلب الحجز…'}try{const clientRequestId=window.__reservationRequestId||(window.__reservationRequestId=crypto.randomUUID());const r=await api('/api/reservations',{method:'POST',body:JSON.stringify({assetId:id,name,phone,fromAt:from?new Date(from).toISOString():null,toAt:to?new Date(to).toISOString():null,clientRequestId})});window.__reservationRequestId=null;rememberTrackedRequest(r,phone);closeModal();showSubmittedRequest(r,'تم استلام طلب الحجز، وسيتم تأكيده بعد مراجعة الإدارة والاتفاق على الشروط')}catch(e){window.__reservationBusy=false;if(btn){btn.disabled=false;btn.textContent='إرسال طلب الحجز'}if(err)err.textContent=e.message||'تعذر إرسال الطلب؛ حاول مجددًا.'}}
function offer(id){window.__offerBusy=false;modal(`<h3>تقديم عرض شراء</h3><p class="muted">أرسل قيمة العرض التي تقترحها؛ قبول العرض النهائي من اختصاص إدارة الحوش.</p><div class="field"><label for="on">الاسم *</label><input id="on" class="input" required minlength="2" autocomplete="name"></div><div class="field"><label for="op">الجوال *</label><input id="op" class="input" type="tel" required inputmode="tel" autocomplete="tel"></div><div class="field"><label for="oa">قيمة العرض *</label><input id="oa" class="input" type="number" min="1" step="0.01" required inputmode="decimal" placeholder="المبلغ المقترح"></div><div class="field"><label for="om">ملاحظة (اختياري)</label><textarea id="om" class="input" maxlength="1000"></textarea></div><p id="offerFormError" class="error" role="alert"></p><button id="offerFormBtn" class="btn primary" onclick="sendOffer('${id}')">إرسال العرض</button>`)}
async function sendOffer(id){if(window.__offerBusy)return;const name=$('#on')?.value.trim()||'',phone=$('#op')?.value.trim()||'',amount=Number($('#oa')?.value),note=$('#om')?.value.trim()||'',err=$('#offerFormError');if(name.length<2||phone.replace(/\D/g,'').length<7||!Number.isFinite(amount)||amount<=0){if(err)err.textContent='أدخل الاسم ورقم جوال صحيحًا وقيمة عرض أكبر من صفر.';return}const btn=document.querySelector('#offerFormBtn');window.__offerBusy=true;if(btn){btn.disabled=true;btn.textContent='جارٍ إرسال العرض…'}try{const clientRequestId=window.__offerRequestId||(window.__offerRequestId=crypto.randomUUID());const r=await api('/api/offers',{method:'POST',body:JSON.stringify({assetId:id,name,phone,amount,note,clientRequestId})});window.__offerRequestId=null;rememberTrackedRequest(r,phone);closeModal();showSubmittedRequest(r,'تم إرسال عرض الشراء بنجاح')}catch(e){window.__offerBusy=false;if(btn){btn.disabled=false;btn.textContent='إرسال العرض'}if(err)err.textContent=e.message||'تعذر إرسال العرض؛ حاول مجددًا.'}}
async function dashboard(tab='overview',fromHistory=false){const previousTabsScroll=document.querySelector('.tabs')?.scrollLeft||0;state.tab=tab;if(!navigator.onLine){return offlineAdminHome()}const d=await api('/api/admin/dashboard');const nav=[['overview','الرئيسية'],['assets','الأصول'],['storage','التخزين'],['reservations','الحجوزات'],['offers','العروض'],['orders','الطلبات'],['finance','المالية'],['invoices','الفواتير'],['contracts','العقود'],['locations','مواقع الحوش'],['conditions','محاضر الاستلام والتسليم'],['users','المستخدمون'],...(state.me?.role==='ADMIN'?[['permissions','الأدوار والصلاحيات']]:[]),['owners','الملاك'],['categories','التصنيفات'],['vehicleTypes','أنواع المركبات'],['inquiries','الاستفسارات'],['reports','التقارير'],['settings','إعدادات النظام'],['audit','سجل التدقيق']];document.querySelector('#app').innerHTML=adminShell(`<main class="container"><div class="panel"><h2>لوحة الإدارة — ${esc(d.system.name)}</h2><div class="tabs">${nav.map(x=>`<button class="btn ${tab===x[0]?'active':''}" onclick="dashboard('${x[0]}')">${x[1]}</button>`).join('')}</div></div><div id="dashContent">${tab==='overview'?overview(d):''}</div></main>`);const newTabs=document.querySelector('.tabs');if(newTabs){newTabs.scrollLeft=previousTabsScroll;requestAnimationFrame(()=>{const current=document.querySelector('.tabs');if(current)current.scrollLeft=previousTabsScroll})}if(tab!=='overview')await loadTab(tab);if(!fromHistory)navigate({view:'dashboard',tab},`#dashboard-${tab}`)}
function overview(d){return `<div class="stats"><div class="stat">الأصول الحالية<strong>${d.counts.assets}</strong></div><div class="stat">توقيف<strong>${d.counts.storage}</strong></div><div class="stat">بيع<strong>${d.counts.sale}</strong></div><div class="stat">إيجار<strong>${d.counts.rent}</strong></div><div class="stat">حجوزات معلقة<strong>${d.counts.reservations}</strong></div><div class="stat">استفسارات<strong>${d.counts.inquiries}</strong></div><div class="stat">عروض<strong>${d.counts.offers}</strong></div></div><div class="panel"><h3>المالية</h3><div class="stats"><div class="stat">الدخل<strong>${money(d.finance.income)}</strong></div><div class="stat">المصروف<strong>${money(d.finance.expense)}</strong></div><div class="stat">الصافي<strong>${money(d.finance.net)}</strong></div></div></div>`}
function filterAdminRows(searchId,statusId,tableId){const q=(document.getElementById(searchId)?.value||'').trim().toLocaleLowerCase('ar');const status=document.getElementById(statusId)?.value||'';const table=document.getElementById(tableId);if(!table)return;let shown=0;table.querySelectorAll('tr[data-request-row]').forEach(row=>{const matchesText=!q||row.textContent.toLocaleLowerCase('ar').includes(q);const matchesStatus=!status||row.dataset.status===status;row.hidden=!(matchesText&&matchesStatus);if(!row.hidden)shown++});const count=document.getElementById(tableId+'Count');if(count)count.textContent=`${shown} نتيجة`; }
async function loadTab(tab){const el=$('#dashContent');if(tab==='assets'){const xs=await api('/api/admin/assets');el.innerHTML=`<div class="panel"><div class="toolbar"><button class="btn primary btn-add-asset" onclick="assetForm()">＋ إضافة أصل جديد</button><input id="aq" class="input" placeholder="بحث: اسم المالك أو AST أو REC أو الموقع..." oninput="filterAssets(this.value)"></div><div class="tablewrap"><table><thead><tr><th>المالك وبيانات الهوية</th><th>نوع المركبة / المعدة</th><th>الموديل</th><th>الكود</th><th>الغرض</th><th>الحالة</th><th>الموقع</th><th>أضافه</th><th>الإظهار</th><th></th></tr></thead><tbody id="assetRows">${assetRows(xs)}</tbody></table></div></div>`}
else if(tab==='storage'){const xs=await api('/api/admin/storage');el.innerHTML=`<div class="panel"><h3>التخزين</h3><div class="tablewrap"><table><tr><th>الأصل</th><th>الأيام</th><th>المستحق</th><th>المدفوع</th><th>المتبقي</th><th></th></tr>${xs.map(x=>`<tr><td>${esc(x.asset?.title)}</td><td>${x.accrued.days}</td><td>${money(x.accrued.current)}</td><td>${money(x.accrued.charge?.paid||0)}</td><td>${money(Math.max(0,(x.accrued.current||x.total||0)-(x.accrued.charge?.paid||0)))}</td><td>${x.accrued.charge?`<button class="btn" onclick="storagePay('${x.id}')">دفعة</button>`:''}</td></tr>`).join('')}</table></div></div>`}
else if(tab==='reservations'){const xs=await api('/api/admin/reservations');el.innerHTML=`<div class="panel"><h3>الحجوزات</h3><div class="admin-request-filters"><div class="field"><label for="adminReservationSearch">بحث بالرقم أو الأصل أو العميل</label><input id="adminReservationSearch" class="input" type="search" oninput="filterAdminRows('adminReservationSearch','adminReservationStatus','adminReservationTable')" placeholder="اكتب كلمة للبحث…"></div><div class="field"><label for="adminReservationStatus">الحالة</label><select id="adminReservationStatus" class="select" onchange="filterAdminRows('adminReservationSearch','adminReservationStatus','adminReservationTable')"><option value="">كل الحالات</option><option value="PENDING">بانتظار التأكيد</option><option value="CONFIRMED">مؤكد</option><option value="COMPLETED">مكتمل</option><option value="REJECTED">مرفوض</option><option value="CANCELLED">ملغى</option></select></div><strong id="adminReservationTableCount">${xs.length} نتيجة</strong></div><div class="tablewrap"><table id="adminReservationTable"><thead><tr><th>رقم الحجز</th><th>الأصل</th><th>العميل</th><th>من</th><th>إلى</th><th>الحالة</th><th></th></tr></thead><tbody>${xs.map(r=>`<tr data-request-row data-status="${esc(r.status||'PENDING')}"><td>${esc(r.code||r.id)}</td><td>${esc(r.asset?.title)}</td><td>${esc(r.customer?.name)}<br>${esc(r.customer?.phone)}</td><td>${esc(dateText(r.fromAt))}</td><td>${esc(r.toAt?dateText(r.toAt):'مفتوح')}</td><td>${statusArabic(r.status)}${r.reservationType==='RENT'&&r.rentalStatus==='ACTIVE'?(r.toAt&&new Date(r.toAt).getTime()<Date.now()?'<br><small style="color:#b45309">متأخر عن موعد الإرجاع</small>':'<br><small>الإيجار: الأصل لدى المستأجر</small>'):r.rentalStatus==='RETURNED'?'<br><small>تم إرجاع الأصل</small>':''}${r.contractCode?`<br><small>العقد: ${esc(r.contractCode)}</small>`:''}${r.depositAmount?`<br><small>العربون: ${money(r.depositAmount)}</small>`:''}</td><td>${r.status==='PENDING'?`<button class="btn" onclick="reservationStatus('${r.id}','CONFIRMED')">تأكيد بعربون</button> <button class="btn danger" onclick="reservationStatus('${r.id}','REJECTED')">رفض</button>`:r.status==='CONFIRMED'?`<button class="btn" onclick="reservationStatus('${r.id}','COMPLETED')">تسليم / إتمام</button> <button class="btn danger" onclick="reservationStatus('${r.id}','CANCELLED')">إلغاء الحجز</button>`:r.status==='COMPLETED'&&r.reservationType==='RENT'&&r.rentalStatus==='ACTIVE'?`<button class="btn primary" onclick="returnRental('${r.id}')">تسجيل إرجاع الأصل</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>`}
else if(tab==='offers'){const xs=await api('/api/admin/offers');el.innerHTML=`<div class="panel"><h3>عروض الشراء</h3><div class="admin-request-filters"><div class="field"><label for="adminOfferSearch">بحث بالرقم أو الأصل أو العميل أو الجوال</label><input id="adminOfferSearch" class="input" type="search" oninput="filterAdminRows('adminOfferSearch','adminOfferStatus','adminOfferTable')" placeholder="اكتب كلمة للبحث…"></div><div class="field"><label for="adminOfferStatus">الحالة</label><select id="adminOfferStatus" class="select" onchange="filterAdminRows('adminOfferSearch','adminOfferStatus','adminOfferTable')"><option value="">كل الحالات</option><option value="OPEN">بانتظار القرار</option><option value="ACCEPTED">مقبول</option><option value="REJECTED">مرفوض</option></select></div><strong id="adminOfferTableCount">${xs.length} نتيجة</strong></div><div class="tablewrap"><table id="adminOfferTable"><thead><tr><th>رقم العرض</th><th>الأصل</th><th>العميل</th><th>العرض</th><th>الحالة</th><th></th></tr></thead><tbody>${xs.map(o=>`<tr data-request-row data-status="${esc(o.status||'OPEN')}"><td>${esc(o.code||o.id)}</td><td>${esc(o.asset?.title)}</td><td>${esc(o.name)}<br>${esc(o.phone)}</td><td>${money(o.amount)}</td><td>${statusArabic(o.status)}</td><td>${o.status==='OPEN'?`<button class="btn" onclick="offerStatus('${o.id}','ACCEPTED')">قبول</button> <button class="btn danger" onclick="offerStatus('${o.id}','REJECTED')">رفض</button>`:'تمت المعالجة'}</td></tr>`).join('')}</tbody></table></div></div>`}
else if(tab==='orders'){const xs=await api('/api/admin/orders');el.innerHTML=`<div class="panel"><div class="toolbar"><button class="btn primary" onclick="orderForm()">＋ تسجيل طلب جديد</button></div><table><tr><th>رقم الطلب</th><th>العميل</th><th>نوع الطلب</th><th>الطلب</th><th>الأصل</th><th>المبلغ</th><th>الحالة</th><th></th></tr>${xs.map(o=>`<tr><td>${esc(o.id)}</td><td>${esc(o.customerName)}<br>${esc(o.phone)}</td><td>${esc(o.type)}</td><td>${esc(o.description)}</td><td>${esc(o.asset?.title||'-')}</td><td>${o.amount?money(o.amount):'-'}</td><td>${esc(o.status)}</td><td>${o.status==='NEW'?`<button class="btn" onclick="orderStatus('${o.id}','IN_PROGRESS')">بدء</button>`:''}${o.status==='IN_PROGRESS'?`<button class="btn success" onclick="orderStatus('${o.id}','COMPLETED')">إتمام</button>`:''}</td></tr>`).join('')}</table></div>`}
else if(tab==='finance'){const [xs,rec]=await Promise.all([api('/api/admin/transactions'),api('/api/admin/finance/reconciliation')]);el.innerHTML=`<div class="panel"><button class="btn primary" onclick="financeForm()">إضافة حركة مالية</button><h3>مطابقة مالية أولية</h3><div class="stats"><div class="stat">الحركات<strong>${rec.transactionCount}</strong></div><div class="stat">السندات<strong>${rec.receiptCount}</strong></div><div class="stat">سندات بلا حركة<strong>${rec.orphanReceipts.length}</strong></div><div class="stat">حركات سندات بلا سند<strong>${rec.orphanReceiptTransactions.length}</strong></div><div class="stat">مصادر مكررة<strong>${rec.duplicateSources.length}</strong></div><div class="stat">حركات معكوسة<strong>${rec.reversedCount}</strong></div><div class="stat">اختلافات الفواتير<strong>${rec.invoiceMismatches?.length||0}</strong></div><div class="stat">اختلافات التخزين<strong>${rec.storageMismatches?.length||0}</strong></div></div>${(rec.invoiceMismatches?.length||rec.storageMismatches?.length)?`<div class="notice">توجد اختلافات تحتاج مراجعة: ${rec.invoiceMismatches?.length||0} فاتورة و${rec.storageMismatches?.length||0} رسوم تخزين.</div>`:''}<p class="muted">المطابقة تنبّه إلى الروابط المفقودة أو مصادر الحركة المتكررة، ولا تعدّ بحد ذاتها اعتمادًا محاسبيًا نهائيًا.</p><div class="tablewrap"><table><tr><th>النوع</th><th>التصنيف</th><th>المبلغ</th><th>الوصف</th><th>تاريخ الحركة</th><th>الحالة / الإجراء</th></tr>${xs.map(x=>`<tr><td>${x.type==='INCOME'?'دخل':'مصروف'}</td><td>${esc(x.category||'أخرى')}</td><td>${money(x.amount)}</td><td>${esc(x.description)}</td><td>${esc(dateText(x.transactionDate||x.createdAt))}</td><td>${x.reversalOf?`عكس للحركة ${esc(x.reversalOf)}`:x.reversedBy?`تم عكسها (${esc(x.reversedBy)})`:`<button class="btn danger" onclick="reverseFinance('${x.id}')">عكس الحركة</button>`}</td></tr>`).join('')}</table></div></div>`}
else if(tab==='invoices'){const [xs,rec]=await Promise.all([api('/api/admin/invoices'),api('/api/admin/finance/reconciliation')]);el.innerHTML=`<div class="panel"><button class="btn primary" onclick="invoiceForm()">إصدار فاتورة</button>${rec.invoiceMismatches?.length?`<div class="notice">تنبيه مطابقة: توجد ${rec.invoiceMismatches.length} فاتورة تحتاج إلى مراجعة ربطها بالحركات المالية.</div>`:''}<table><tr><th>رقم</th><th>الطرف</th><th>الإجمالي</th><th>المدفوع</th><th>المتبقي</th><th>الحالة / الاعتماد</th><th>الإجراء</th></tr>${xs.map(x=>`<tr><td>${esc(x.number)}</td><td>${esc(x.partyName)}</td><td>${money(x.total)}</td><td>${money(x.paid)}</td><td>${money(x.balance)}</td><td>${statusArabic(x.status)}</td><td><button class="btn primary" onclick="recordInvoicePayment('${x.id}',${Number(x.balance||0)})">تسجيل دفعة</button> <button class="btn" onclick="refundInvoice('${x.id}',${Number(x.paid||0)})">استرداد مبلغ</button> <button class="btn" onclick="adjustInvoicePaid('${x.id}',${Number(x.paid||0)},${Number(x.total||0)})">تسوية المدفوع</button></td></tr>`).join('')}</table></div>`}
else if(tab==='contracts'){const xs=await api('/api/admin/contracts');el.innerHTML=`<div class="panel"><button class="btn primary" onclick="contractForm()">إنشاء اتفاقية</button><p class="muted">قوالب ورقية للبيع والإيجار والتخزين والوساطة، مع حفظ بيانات الطرفين وقت إنشاء العقد.</p><div class="tablewrap"><table><tr><th>رقم العقد</th><th>نوع الاتفاقية</th><th>الأصل</th><th>الطرف الآخر</th><th>الهاتف</th><th>القيمة</th><th>الحالة / الاعتماد</th><th>الإجراء</th></tr>${xs.map(x=>`<tr><td>${esc(x.code||x.id)}</td><td>${contractTypeArabic(x.type)}</td><td>${esc(x.asset?.title||x.assetSnapshot?.title||'')}</td><td>${esc(x.partyName)}</td><td>${esc(x.partyPhone)}</td><td>${money(x.amount)}</td><td>${statusArabic(x.status)}${x.approvedAt?`<div class="muted" style="font-size:11px">اعتمد: ${esc(new Date(x.approvedAt).toLocaleDateString('ar-SA'))} — ${esc(x.approvedByName||'الإدارة')}</div><div class="muted" style="font-size:11px">سلامة لقطة الاعتماد: ${x.integrityStatus==='VERIFIED'?'مطابقة': 'تحتاج مراجعة'}</div>`:''}</td><td><button class="btn" onclick="contractPaper('${x.id}')">معاينة / طباعة</button> ${x.status==='DRAFT'?`<button class="btn primary" onclick="approveContract('${x.id}')">اعتماد العقد</button>`:''}</td></tr>`).join('')}</table></div></div>`}
else if(tab==='locations'){const xs=await api('/api/admin/locations');el.innerHTML=`<div class="panel"><button class="btn primary" onclick="locationForm()">إضافة موقع</button><div class="tablewrap"><table><tr><th>الرمز</th><th>الاسم</th><th>المنطقة</th><th>عدد الأصول</th><th>الحالة</th><th>الإجراء</th></tr>${xs.map(x=>`<tr><td>${esc(x.code)}</td><td>${esc(x.name)}</td><td>${esc(x.zone||'-')}</td><td>${x.assetCount}</td><td>${x.active===false?'غير نشط':'نشط'}</td><td><button class="btn" onclick='locationForm(${JSON.stringify(x)})'>تعديل</button></td></tr>`).join('')}</table></div></div>`}
else if(tab==='conditions'){const xs=await api('/api/admin/conditions');el.innerHTML=`<div class="panel"><h3>محاضر الاستلام والتسليم</h3><p class="muted">المحضر يوثق حالة الأصل عند دخوله أو خروجه من الحوش، مثل الحالة الظاهرية والعداد وساعات التشغيل والملحقات والملاحظات، مع تسجيل الموظف والتاريخ.</p><button class="btn primary" onclick="conditionForm()">إضافة محضر استلام/تسليم</button><div class="tablewrap"><table><tr><th>الأصل</th><th>النوع</th><th>الحالة</th><th>العداد</th><th>الساعات</th><th>المسؤول</th><th>الملاحظات</th><th>الإجراء</th></tr>${xs.map(x=>`<tr><td>${esc(x.asset?.title)}</td><td>${x.type==='ENTRY'?'استلام / دخول':'تسليم / خروج'}</td><td>${esc(x.condition)}</td><td>${esc(x.odometer||'-')}</td><td>${esc(x.engineHours||'-')}</td><td>${esc(x.user?.name||'-')}</td><td>${esc(x.notes||'-')}</td><td><button class="btn" onclick="conditionDetails('${x.id}')">عرض / طباعة</button></td></tr>`).join('')}</table></div></div>`}
else if(tab==='owners'){const xs=await api('/api/admin/owners?q=');el.innerHTML=`<div class="panel"><div class="section-head"><div><h3>الملاك</h3><p class="muted">كل مالك يُسجل مرة واحدة ويمكن ربط عدة مركبات ومعدات به.</p></div><button class="btn primary" onclick="ownerForm()">إضافة مالك</button></div><table><tr><th>المالك</th><th>الجوال</th><th>نوع الهوية</th><th>رقم الهوية</th><th>الأصول</th><th></th></tr>${xs.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.phone)}</td><td>${identityName(x.identityType)}</td><td>${esc(x.identityNumber)}</td><td>${x.assetCount||0}</td><td><button class="btn" onclick='ownerForm(${JSON.stringify(x)})'>تعديل</button></td></tr>`).join('')}</table></div>`}
else if(tab==='permissions'){const data=await api('/api/admin/role-permissions');const selected=window.__permissionRole||'SALES';const labels=Object.fromEntries(data.roles.map(r=>[r,roleLabel(r)]));el.innerHTML=`<div class="panel"><h3>الأدوار والصلاحيات التفصيلية</h3><p class="muted">حدد ما يستطيع كل دور فعله في كل قسم. تُطبّق الصلاحيات على الخادم أيضًا، وليست مجرد إخفاء للأزرار.</p><div class="field"><label>الدور الذي تريد ضبطه</label><select id="permissionRole" class="select" onchange="window.__permissionRole=this.value;loadTab('permissions')">${data.roles.filter(r=>!['ADMIN'].includes(r)).map(r=>`<option value="${r}" ${r===selected?'selected':''}>${esc(labels[r]||r)}</option>`).join('')}</select></div><div class="tablewrap"><table><thead><tr><th>القسم / الخدمة</th>${data.actions.map(a=>`<th>${esc(a.label)}</th>`).join('')}</tr></thead><tbody>${data.resources.map(resource=>`<tr><td><strong>${esc(resource.label)}</strong></td>${data.actions.map(action=>`<td><input aria-label="${esc(resource.label)} - ${esc(action.label)}" type="checkbox" data-permission-resource="${resource.key}" data-permission-action="${action.key}" ${(data.matrix[selected]?.[resource.key]||[]).includes(action.key)?'checked':''}></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="toolbar"><button class="btn primary" onclick="saveRolePermissions()">حفظ صلاحيات الدور</button><button class="btn" onclick="resetRolePermissions()">استعادة الصلاحيات الافتراضية</button></div><p class="muted">لا يمكن تعديل صلاحيات مدير النظام من هذه الشاشة؛ لا يمكن منح صلاحيات تتجاوز دور المستخدم. بعد الحفظ، تؤثر التغييرات في جميع المستخدمين المرتبطين بهذا الدور.</p></div>`}
else if(tab==='users'){const xs=await api('/api/admin/users');el.innerHTML=`<div class="panel"><div class="toolbar"><button class="btn primary" onclick="userForm()">＋ إضافة مستخدم</button><button class="btn success" onclick="userForm();setTimeout(()=>{const r=document.querySelector('#unRole');if(r&&state.me?.role==='ADMIN')r.value='MANAGER'},0)" ${state.me?.role==='ADMIN'?'':'disabled title="هذه الصلاحية متاحة لمدير النظام فقط"'}>＋ إضافة مدير</button></div><table><tr><th>الاسم</th><th>الجوال</th><th>نوع الهوية</th><th>رقم الهوية</th><th>الدور</th><th>الحالة</th><th>أنشأه</th><th>آخر تعديل بواسطة</th><th>الإجراء</th></tr>${xs.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.phone)}</td><td>${identityName(x.identityType)}</td><td>${esc(x.identityNumber)}</td><td>${roleLabel(x.role)}</td><td>${x.active?'نعم':'لا'}</td><td>${x.createdByName?`${esc(x.createdByName)}<br><small>${esc(roleLabel(x.createdByRole))}</small>`:'—'}</td><td>${x.updatedByName?`${esc(x.updatedByName)}<br><small>${esc(roleLabel(x.updatedByRole))}</small>`:'—'}</td><td><button class="btn" onclick='userForm(${JSON.stringify(x)})' ${state.me?.role==='MANAGER'&&['ADMIN','MANAGER'].includes(x.role)?'disabled title="لا يمكن تعديل هذا الدور"':''}>تعديل</button></td></tr>`).join('')}</table></div>`}
else if(tab==='vehicleTypes'){const xs=await api('/api/admin/vehicle-types');el.innerHTML=`<div class="panel"><div class="section-head"><div><h3>إدارة أنواع المركبات</h3><p class="muted">أضف أو عدّل أو عطّل الأنواع التي تظهر عند تسجيل المركبات.</p></div><button class="btn primary" onclick="vehicleTypeForm()">إضافة نوع مركبة</button></div><table><tr><th>النوع</th><th>الحالة</th><th></th></tr>${xs.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.active?'نشط':'معطل'}</td><td><button class="btn" onclick='vehicleTypeForm(${JSON.stringify(x)})'>تعديل</button> <button class="btn danger" onclick="deleteVehicleType('${x.id}')">حذف/تعطيل</button></td></tr>`).join('')}</table></div>`}
else if(tab==='categories'){const xs=await api('/api/admin/categories');el.innerHTML=`<div class="panel"><button class="btn primary" onclick="categoryForm()">إضافة تصنيف</button><table><tr><th>الاسم</th><th>بيع</th><th>إيجار</th><th>توقيف</th><th>نشط</th><th></th></tr>${xs.map(x=>`<tr><td>${x.icon||'📦'} ${esc(x.name)}</td><td>${x.allowSale?'نعم':'لا'}</td><td>${x.allowRent?'نعم':'لا'}</td><td>${x.allowStorage?'نعم':'لا'}</td><td>${x.active?'نعم':'لا'}</td><td><button class="btn" onclick="editCategory('${x.id}')">تعديل</button></td></tr>`).join('')}</table></div>`}
else if(tab==='inquiries'){const xs=await api('/api/admin/inquiries');el.innerHTML=`<div class="panel"><p class="muted">حدّث حالة الاستفسار مع تسجيل سبب واضح؛ تظهر التغييرات في سجل متابعة العميل.</p><div class="admin-request-filters"><div class="field"><label for="adminInquirySearch">بحث بالرقم أو الأصل أو العميل أو الرسالة</label><input id="adminInquirySearch" class="input" type="search" oninput="filterAdminRows('adminInquirySearch','adminInquiryStatus','adminInquiryTable')" placeholder="اكتب كلمة للبحث…"></div><div class="field"><label for="adminInquiryStatus">الحالة</label><select id="adminInquiryStatus" class="select" onchange="filterAdminRows('adminInquirySearch','adminInquiryStatus','adminInquiryTable')"><option value="">كل الحالات</option><option value="OPEN">بانتظار المتابعة</option><option value="IN_PROGRESS">قيد المتابعة</option><option value="CLOSED">مغلقة</option></select></div><strong id="adminInquiryTableCount">${xs.length} نتيجة</strong></div><div class="tablewrap"><table id="adminInquiryTable"><thead><tr><th>رقم</th><th>الأصل</th><th>العميل</th><th>الرسالة</th><th>الحالة</th><th>آخر تحديث</th><th>الإجراء</th></tr></thead><tbody>${xs.map(x=>`<tr data-request-row data-status="${esc(x.status||'OPEN')}"><td>${esc(x.code||x.id)}</td><td>${esc(x.asset?.title||'غير متاح')}<br><small>${esc(x.asset?.code||'')}</small></td><td>${esc(x.name)}<br>${esc(x.phone)}</td><td>${esc(x.message)}</td><td>${statusArabic(x.status)}</td><td>${esc(dateText(x.updatedAt||x.createdAt))}</td><td><button class="btn" onclick="reply('${x.id}')">رد</button> ${x.status==='OPEN'?`<button class="btn primary" onclick="inquiryStatus('${x.id}','IN_PROGRESS')">بدء المتابعة</button>`:x.status==='IN_PROGRESS'?`<button class="btn primary" onclick="inquiryStatus('${x.id}','CLOSED')">إغلاق</button> <button class="btn" onclick="inquiryStatus('${x.id}','OPEN')">إعادة للانتظار</button>`:`<button class="btn" onclick="inquiryStatus('${x.id}','IN_PROGRESS')">إعادة فتح</button>`}</td></tr>`).join('')}</tbody></table></div><p class="muted">يمكنك الجمع بين البحث والحالة لتحديد الاستفسارات التي تحتاج إلى إجراء.</p></div>`}
else if(tab==='reports'){el.innerHTML=`<div class="panel"><div class="toolbar"><button class="btn" onclick="report(30)">30 يومًا</button><button class="btn" onclick="report(90)">90 يومًا</button><button class="btn" onclick="report(365)">سنة</button></div><div id="report"></div></div>`;report(30)}
else if(tab==='settings'){const s=await api('/api/admin/settings'),cs=await api('/api/currencies');el.innerHTML=`<div class="panel"><h3>هوية النظام والإعدادات</h3><div class="two"><div class="field"><label>اسم النظام</label><input id="sn" class="input" value="${esc(s.name)}"></div><div class="field"><label>الوصف المختصر</label><input id="st" class="input" value="${esc(s.tagline)}"></div><div class="field"><label>الدولة</label><input id="sco" class="input" value="${esc(s.country)}"></div><div class="field"><label>المدينة</label><input id="sci" class="input" value="${esc(s.city)}"></div><div class="field"><label>نوع العملة</label><select id="sc" class="select">${cs.map(c=>`<option value="${c.code}" ${c.code===s.currency?'selected':''}>${c.name} (${c.code})</option>`).join('')}</select></div><div class="field"><label>مفتاح الدولة</label><input id="scc" class="input" value="${esc(s.countryCode||'966')}" placeholder="966"></div><div class="field"><label>واتساب</label><input id="sw" class="input" value="${esc(s.whatsapp)}"></div><div class="field"><label>الهاتف</label><input id="sp" class="input" value="${esc(s.phone)}"></div><div class="field"><label>البريد</label><input id="se" class="input" value="${esc(s.email)}"></div><div class="field"><label>العنوان</label><input id="sa" class="input" value="${esc(s.address)}"></div><div class="field"><label>خط العرض (Latitude)</label><input id="sla" class="input" value="${esc(s.latitude||'')}" placeholder="مثال: 24.xxxxxx"></div><div class="field"><label>خط الطول (Longitude)</label><input id="slo" class="input" value="${esc(s.longitude||'')}" placeholder="مثال: 46.xxxxxx"></div><div class="field"><label>رابط الخريطة المباشر</label><input id="smu" class="input" value="${esc(s.mapsUrl||'')}" placeholder="يمكنك لصق رابط Google Maps"></div><div class="field"><label>معاينة الموقع</label><div class="toolbar"><a class="btn" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(s.latitude&&s.longitude?`${s.latitude},${s.longitude}`:(s.address||'الرياض حي السلي مقابل مصنع الألبان'))}">📍 فتح الخريطة</a><span class="muted">احفظ الإحداثيات أو رابط الخريطة ليتم استخدامه في زر الوصول للعميل.</span></div></div><div class="field"><label>سعر التخزين الافتراضي</label><input id="sr" class="input" type="number" value="${s.storageDefaultRate}"></div></div><hr><h3>هوية المستندات والفواتير</h3><p class="muted">اسم المنصة «حوشك» مستقل عن اسم الحوش الذي يظهر في رؤوس السندات والمستندات. التغييرات تحفظ في الإعدادات وتُستخدم عند إنشاء مستندات جديدة.</p><div class="two"><div class="field"><label>اسم الحوش في المستندات</label><input id="syn" class="input" value="${esc(s.yardName||'حوش أبو مناحي')}"></div><div class="field"><label>عنوان الحوش للمستندات</label><input id="sya" class="input" value="${esc(s.yardAddress||s.address||'')}"></div><div class="field"><label>هاتف الحوش للمستندات</label><input id="syp" class="input" value="${esc(s.yardPhone||s.phone||'')}"></div><div class="field"><label>واتساب الحوش للمستندات</label><input id="syw" class="input" value="${esc(s.yardWhatsapp||s.whatsapp||'')}"></div><div class="field"><label>بريد الحوش للمستندات</label><input id="sye" class="input" type="email" value="${esc(s.yardEmail||s.email||'')}"></div><div class="field"><label>رابط شعار الحوش للمستندات</label><input id="syl" class="input" value="${esc(s.yardLogo||s.logo||'')}" placeholder="رابط صورة الشعار"></div></div><hr><h3>محتوى واجهة العميل</h3><p class="muted">هذه النصوص تظهر في صفحة «عن حوشك» والشريط التعريفي أسفل شريط التنقل.</p><div class="three"><div class="field"><label>مالك الحوش</label><input id="son" class="input" value="${esc(s.ownerName||'أبو مناحي السبيعي')}"></div><div class="field"><label>رقم المالك</label><input id="sop" class="input" value="${esc(s.ownerPhone||'00966554795400')}"></div><div class="field"><label>مدير الحوش</label><input id="smn" class="input" value="${esc(s.managerName||'أبو أنس الإدريسي')}"></div><div class="field"><label>رقم المدير</label><input id="smp" class="input" value="${esc(s.managerPhone||'00966507882962')}"></div><div class="field"><label>تطوير وبرمجة</label><input id="sdn" class="input" value="${esc(s.developerName||'هيثم القاضي')}"></div></div><div class="field"><label>عنوان «عن حوشك»</label><input id="sat" class="input" value="${esc(s.aboutTitle||'عن حوشك')}"></div><div class="field"><label>نبذة عن حوشك</label><textarea id="sab" class="input">${esc(s.aboutText||'')}</textarea></div><div class="field"><label>الخدمات التي نقدمها</label><textarea id="ssv" class="input">${esc(s.servicesText||'')}</textarea></div><div class="field"><label>طريقة الاستخدام</label><textarea id="shu" class="input">${esc(s.howToText||'')}</textarea></div><div class="field"><label>التطوير المستقبلي</label><textarea id="sfu" class="input">${esc(s.futureText||'')}</textarea></div><div class="field"><label>رسائل الشريط التعريفي — رسالة في كل سطر</label><textarea id="stm" class="input" rows="5">${esc((s.tickerMessages||[]).join('\n'))}</textarea></div><button class="btn primary" onclick="saveSettings()">حفظ الإعدادات</button></div>`}
else if(tab==='audit'){const xs=await api('/api/admin/audit');el.innerHTML=`<div class="panel"><h3>سجل التدقيق</h3><p class="muted">سجل يوضح من قام بالعملية وماذا تم تغييره ومتى، بصياغة مفهومة للإدارة.</p><div class="tablewrap"><table><tr><th>المسؤول</th><th>العملية</th><th>الكيان</th><th>التفاصيل</th><th>التاريخ</th></tr>${xs.map(x=>`<tr><td><strong>${esc(x.actorName||x.actor?.name||'النظام')}</strong><br><small class="muted">${esc(roleLabel(x.actorRole||x.actor?.role||'SYSTEM'))}</small></td><td>${actionName(x.action)}</td><td>${entityName(x.entity)}</td><td><div class="audit-details">${auditDetails(x.details)||'لا توجد تفاصيل إضافية'}</div></td><td>${esc(dateText(x.createdAt))}</td></tr>`).join('')}</table></div></div>`}stabilizeAdminTables();}
function assetRows(xs){return xs.map(a=>`<tr><td><strong>${esc(a.owner?.name||'الحوش / الإدارة')}</strong><br><small>${a.owner?`${identityName(a.owner.identityType)} · ${esc(a.owner.identityNumber||'')}<br>الهاتف: ${esc(a.owner.phone||'')}`:'-'}</small></td><td>${esc(a.customFields?.vehicleType==='OTHER'?a.customFields?.vehicleTypeOther:(a.customFields?.vehicleTypeName||a.customFields?.vehicleType||a.customFields?.assetType||a.customFields?.equipmentType||a.customFields?.truckType||a.customFields?.headType||a.category?.name||'-'))}</td><td>${esc(a.model||'-')}</td><td>${esc(a.code||'-')}</td><td>${purposeName(a.purpose)}</td><td>${statusName(a.status)}</td><td>${esc(a.locationCode||'-')}</td><td>${esc(a.createdBy?.name||'-')}</td><td>${a.publicVisible?'نعم':'لا'}</td><td><button class="btn" onclick="assetRecord('${a.id}')">السجل</button> <button class="btn" onclick="showAssetQR('${a.id}')">▣ QR</button> <button class="btn" onclick="editAsset('${a.id}')">تعديل</button>${a.status!=='EXITED'?` <button class="btn danger" onclick="exitAsset('${a.id}')">خروج</button>`:''}</td></tr>`).join('')}

async function showAssetQR(id){try{const a=await api('/api/admin/assets/'+id);if(!a.publicToken)throw Error('رمز الباركود غير متوفر لهذا الأصل');const url=location.origin+'/asset/'+encodeURIComponent(a.publicToken);modal(`<div class="qr-panel"><h3>باركود الأصل</h3><p><strong>${esc(a.title)}</strong><br>كود الأصل: <strong>${esc(a.code)}</strong><br>رابط السجل العام: لا يعرض بيانات المالك أو رقمه.</p><div id="assetQrBox" style="display:flex;justify-content:center;margin:18px 0"></div><div class="toolbar"><button class="btn primary" onclick="printAssetQR('${a.id}')">🖨️ طباعة بطاقة الباركود</button><button class="btn" onclick="navigator.clipboard?.writeText(${JSON.stringify(url)});alert('تم نسخ رابط الباركود')">نسخ الرابط</button></div></div>`);if(typeof QRCode==='undefined')throw Error('تعذر تحميل مولد QR');new QRCode(document.getElementById('assetQrBox'),{text:url,width:220,height:220,correctLevel:QRCode.CorrectLevel.M});window.__assetQR={a,url}}catch(e){alert(e.message)}}
async function printAssetQR(id){try{const a=await api('/api/admin/assets/'+id);if(!a.publicToken)throw Error('رمز الباركود غير متوفر');const url=location.origin+'/asset/'+encodeURIComponent(a.publicToken);const w=window.open('','_blank');if(!w)throw Error('اسمح بالنوافذ المنبثقة للطباعة');w.document.write(`<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>بطاقة ${esc(a.code)}</title><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"><\/script><style>body{font-family:Arial,sans-serif;text-align:center;padding:30px}.card{width:340px;margin:auto;border:1px solid #ddd;border-radius:18px;padding:24px}h2{margin:0 0 8px}#q{display:flex;justify-content:center;margin:20px}</style></head><body><div class="card"><h2>حوشك</h2><strong>${esc(a.title)}</strong><div>كود الأصل: ${esc(a.code)}</div><div id="q"></div><p>امسح الباركود لمعرفة تفاصيل الأصل والتواصل مع إدارة الحوش.</p></div><script>new QRCode(document.getElementById('q'),{text:${JSON.stringify(url)},width:220,height:220});setTimeout(()=>window.print(),500);<\/script></body></html>`);w.document.close()}catch(e){alert(e.message)}}
async function assetRecord(id){try{const a=await api('/api/admin/assets/'+id);modal(`<h3>سجل الأصل — ${esc(a.title)}</h3><div class="toolbar"><button class="btn primary" onclick="entryReceipt('${a.id}')">📄 سند استلام الأصل</button><button class="btn success" onclick="paymentReceiptForm('${a.id}')">💰 سند استلام مبلغ</button><button class="btn" onclick="showAssetQR('${a.id}')">▣ باركود / QR</button></div><div class="stats"><div class="stat">المالك<strong>${esc(a.owner?.name||'الحوش / الإدارة')}</strong><small>${esc(a.owner?.phone||'')}</small></div><div class="stat">أضافه<strong>${esc(a.createdBy?.name||'-')}</strong></div><div class="stat">آخر تعديل<strong>${esc(a.lastUpdatedBy?.name||'-')}</strong></div><div class="stat">التسليم / الخروج<strong>${esc(a.exitBy?.name||'-')}</strong></div></div><div class="field-section"><h4>سجل الإجراءات</h4>${(a.history||[]).map(h=>`<div class="audit-item"><strong>${esc(h.note||'إجراء')}</strong><span>${esc(h.changedBy?.name||'النظام')} — ${esc(dateText(h.createdAt))}</span></div>`).join('')||'<div class="muted">لا توجد إجراءات إضافية.</div>'}</div><div class="field-section"><h4>محاضر الاستلام والتسليم</h4>${(a.conditions||[]).map(c=>`<div class="audit-item"><strong>${c.type==='ENTRY'?'استلام / دخول':'تسليم / خروج'}</strong><span>${esc(c.user?.name||'النظام')} — ${esc(dateText(c.createdAt))}</span><small>${esc(c.condition||'')} ${esc(c.notes||'')}</small></div>`).join('')||'<div class="muted">لا توجد محاضر.</div>'}</div>`)}catch(e){alert(e.message)}}
function stabilizeAdminTables(){const root=$('#dashContent');if(!root)return;root.querySelectorAll('table').forEach(t=>{if(t.parentElement?.classList.contains('tablewrap'))return;const w=document.createElement('div');w.className='tablewrap';t.parentNode.insertBefore(w,t);w.appendChild(t)});}

function filterAssets(q){api('/api/admin/assets?q='+encodeURIComponent(q)).then(xs=>$('#assetRows').innerHTML=assetRows(xs))}
async function assetForm(a={}){window.__assetEdit=a;window.__returnToAsset=false;window.__assetSaveBusy=false;window.__assetRequestId=a.id?null:crypto.randomUUID();let owners=[];try{owners=await api('/api/admin/owners?q=')}catch{owners=offlineCache().owners||[]}let vtypes=[];try{vtypes=await api('/api/vehicle-types')}catch{vtypes=offlineCache().vehicleTypes||[]}const selectedCat=state.cats.find(c=>c.id===a.categoryId)||state.cats[0]||{};const purpose=a.purpose||'SALE';const ownerIsYard=a.ownerType==='USER'||(a.ownerId&&state.me&&a.ownerId===state.me.id);const cf=a.customFields||{};const selectedOwner=owners.find(x=>x.id===a.ownerId);const entryLocal=a.entryAt?toLocalInputValue(a.entryAt):toLocalInputValue(new Date().toISOString());modal(`<h3>${a.id?'تعديل أصل':'إضافة أصل جديد'}</h3><div class="purpose-grid"><button type="button" class="purpose-card ${purpose==='SALE'?'selected':''}" data-purpose="SALE" onclick="selectAssetPurpose('SALE')"><span>💰</span><strong>للبيع</strong><small>عرض الأصل للبيع</small></button><button type="button" class="purpose-card ${purpose==='RENT'?'selected':''}" data-purpose="RENT" onclick="selectAssetPurpose('RENT')"><span>🔑</span><strong>للإيجار</strong><small>عرض الأصل للإيجار</small></button><button type="button" class="purpose-card ${purpose==='STORAGE'?'selected':''}" data-purpose="STORAGE" onclick="selectAssetPurpose('STORAGE')"><span>🏠</span><strong>للتوقيف</strong><small>تخزين فقط داخل الحوش</small></button><button type="button" class="purpose-card ${purpose==='SALE_RENT'?'selected':''}" data-purpose="SALE_RENT" onclick="selectAssetPurpose('SALE_RENT')"><span>🔄</span><strong>للبيع والإيجار</strong><small>إتاحة الغرضين</small></button></div><input id="ap" type="hidden" value="${purpose}"><input id="as" type="hidden" value="${a.status||'ACTIVE'}"><div class="field"><label>القسم</label><select id="ag" class="select" onchange="renderDynamicAssetFields();updatePurposeCards();updateAssetPriceFields()">${state.cats.map(c=>`<option value="${c.id}" ${c.id===selectedCat.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field-section owner-section"><h4>بيانات المالك</h4><label class="checkline"><input id="aoy" type="checkbox" ${ownerIsYard?'checked':''} onchange="toggleOwnerChoice()"> المالك هو الحوش / الإدارة</label><div id="ownerPicker" class="owner-picker" style="display:${ownerIsYard?'none':'block'}"><label>اسم المالك</label><input id="aoSearch" class="input" autocomplete="off" placeholder="اكتب اسم المالك للبحث أو لإضافة مالك جديد" value="${esc(selectedOwner?.name||'')}" oninput="$('#ao').value='';setOwnerFieldsEditable(true);searchOwners(this.value)"><input id="ao" type="hidden" value="${esc(selectedOwner?.id||'')}"><div id="ownerSuggestions" class="owner-suggestions"></div><div id="newOwnerFields" class="new-owner-fields" style="display:block"><p id="ownerFieldsHint" class="muted">أدخل بيانات المالك الجديد، أو اختر مالكًا موجودًا من الاقتراحات وسيتم تعبئة بياناته تلقائيًا.</p><div class="two"><div class="field"><label>نوع الهوية</label><select id="noi" class="select"><option value="NATIONAL_ID">هوية وطنية</option><option value="PERSONAL_ID">بطاقة شخصية</option><option value="RESIDENCY_ID">هوية مقيم</option><option value="PASSPORT">جواز سفر</option><option value="OTHER">هوية أخرى</option></select></div><div class="field"><label>رقم الهوية</label><input id="non" class="input" autocomplete="off"></div></div><div class="field"><label>رقم الهاتف</label><input id="nop" class="input" autocomplete="tel"></div></div><div id="selectedOwnerInfo" class="selected-owner"></div></div></div><div class="field-section"><h4>بيانات الدخول</h4><div class="field"><label>تاريخ ووقت الدخول</label><input id="ae" class="input" type="datetime-local" value="${entryLocal}"><small class="muted">يُسجل تلقائيًا بتاريخ ووقت النظام، ويمكن تعديله عند الحاجة.</small></div></div><div id="dynamicFields"></div><div id="priceFields"></div><div class="two"><div class="field"><label>موقع الحوش / الأصل <span class="muted">(اختياري)</span></label><input id="al" class="input" placeholder="اكتب الوصف أو الرمز" value="${esc(a.locationCode)}"></div><div class="field"><label>كود الأصل</label><input id="ac" class="input" value="${esc(a.code||'')}" readonly placeholder="يُنشأ تلقائيًا"></div></div><div class="field"><label>اسم العرض / العنوان</label><input id="at" class="input" value="${esc(a.title||'')}" readonly placeholder="يُولد تلقائيًا من بيانات الأصل"></div><div class="field"><label>الوصف</label><textarea id="ad" class="input" placeholder="تفاصيل إضافية عن الأصل">${esc(a.description)}</textarea></div><section class="temporary-offer-editor"><h4>🏷️ عرض مؤقت للعميل</h4><p class="muted">يظهر مستطيل العرض في صفحة الإعلان قبل الصور، ويختفي تلقائيًا عند انتهاء المدة. عند إيقافه تعود الصور إلى موضعها الطبيعي.</p><label class="checkline"><input id="promoActive" type="checkbox" ${a.promoActive&&a.promoEndsAt&&new Date(a.promoEndsAt).getTime()>Date.now()?"checked":""}> تفعيل العرض المؤقت</label><div class="field"><label>عنوان العرض</label><input id="promoTitle" class="input" maxlength="90" value="${esc(a.promoTitle||"عرض لفترة محدودة")}" placeholder="مثال: سعر خاص لمدة محدودة"></div><div class="field"><label>تفاصيل العرض</label><textarea id="promoDescription" class="input" maxlength="300" placeholder="مثال: تخفيض خاص عند التواصل اليوم">${esc(a.promoDescription||"")}</textarea></div><div class="two"><div class="field"><label>سعر العرض (اختياري)</label><input id="promoPrice" class="input" type="number" min="0" step="0.01" value="${esc(a.promoPrice??"")}" placeholder="اتركه فارغًا إذا لا يوجد سعر خاص"></div><div class="field"><label>مدة العرض</label><select id="promoDurationHours" class="select"><option value="24" ${Number(a.promoDurationHours||24)===24?"selected":""}>24 ساعة — يوم واحد</option><option value="48" ${Number(a.promoDurationHours||24)===48?"selected":""}>48 ساعة — يومان</option><option value="72" ${Number(a.promoDurationHours||24)===72?"selected":""}>72 ساعة — ثلاثة أيام</option></select></div></div>${a.promoEndsAt?`<p class="muted">نهاية العرض المسجلة: ${esc(new Date(a.promoEndsAt).toLocaleString("ar-SA"))}${new Date(a.promoEndsAt).getTime()<=Date.now()?" — انتهى العرض":""}</p>`:""}</section><div class="field"><label>ملاحظات الدخول</label><textarea id="an" class="input">${esc(a.entryNotes)}</textarea></div><div class="field"><label>صور الأصل</label><div class="image-upload-actions"><label class="btn primary image-pick"><span>📁 اختيار صور من الهاتف</span><input id="ai" type="file" multiple accept="image/*"></label><label class="btn success image-pick"><span>📷 فتح الكاميرا وتصوير المعدة</span><input id="aiCamera" type="file" accept="image/*" capture="environment"></label></div><div id="imageSelectionInfo" class="muted image-selection-info">يمكن اختيار صور من الجهاز أو فتح الكاميرا مباشرة لتصوير المعدة.</div>${a.id?`<div class="existing-asset-images"><h4>الصور المحفوظة</h4>${(a.images||[]).length?(a.images||[]).slice().sort((x,y)=>(x.sortOrder||0)-(y.sortOrder||0)).map((im,i)=>`<div class="existing-image-row"><img src="${esc(im.url)}" alt="صورة الأصل ${i+1}" loading="lazy"><div><strong>${i===0?'الصورة الرئيسية':`صورة ${i+1}`}</strong><small>${esc(im.filename||'صورة محفوظة')}</small><div class="image-row-actions">${i!==0?`<button type="button" class="btn" onclick="setAssetImagePrimary('${a.id}','${im.id}')">جعلها الرئيسية</button>`:''}<button type="button" class="btn danger" onclick="deleteAssetImage('${a.id}','${im.id}')">حذف الصورة</button></div></div></div>`).join(''):`<p class="muted">لا توجد صور محفوظة لهذا الأصل حتى الآن.</p>`}</div>`:''}<small class="muted">يمكن إضافة عدة صور، وتظهر للمستخدم على شكل شبكة. تُحفظ الصور الجديدة عند الضغط على حفظ التعديلات.</small></div><button id="assetSaveBtn" class="btn primary btn-save-asset" onclick="saveAsset('${a.id||''}')">${a.id?'حفظ التعديلات':'＋ إضافة الأصل وحفظ'}</button>`);window.__vehicleTypes=vtypes;window.__owners=owners;renderDynamicAssetFields(cf);toggleOwnerChoice();updatePurposeCards();updateAssetPriceFields();renderSelectedOwner(selectedOwner);if(selectedOwner){if($('#noi'))$('#noi').value=selectedOwner.identityType||'NATIONAL_ID';if($('#non'))$('#non').value=selectedOwner.identityNumber||'';if($('#nop'))$('#nop').value=selectedOwner.phone||'';setOwnerFieldsEditable(false);searchOwners(selectedOwner.name)}else setOwnerFieldsEditable(true);['ai','aiCamera'].forEach(id=>{const el=$('#'+id);if(el)el.addEventListener('change',updateImageSelectionInfo)});updateImageSelectionInfo()}
function toLocalInputValue(iso){const d=new Date(iso);if(Number.isNaN(d.getTime()))return '';const p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`}

function renderSelectedOwner(o){const el=$('#selectedOwnerInfo');if(!el)return;el.innerHTML=o?`<div><strong>${esc(o.name)}</strong> · ${esc(o.phone)}<br><small>${identityName(o.identityType)} · ${esc(o.identityNumber)} · ${o.assetCount||0} أصل مرتبط</small></div>`:''}
async function searchOwners(q){const box=$('#ownerSuggestions'),newBox=$('#newOwnerFields');if(!box)return;const term=String(q||'').trim();if(!term){box.innerHTML='';if(newBox)newBox.style.display='block';if($('#selectedOwnerInfo'))$('#selectedOwnerInfo').innerHTML='';return}let xs=[];try{xs=await api('/api/admin/owners?q='+encodeURIComponent(term))}catch{const cached=offlineCache().owners||[];const t=term.toLowerCase();xs=cached.filter(o=>[o.name,o.phone,o.identityNumber].filter(Boolean).some(v=>String(v).toLowerCase().includes(t)))}window.__owners=xs;box.innerHTML=xs.map(o=>`<button type="button" class="owner-suggestion" onclick='selectOwner(${JSON.stringify(o)})'><strong>${esc(o.name)}</strong><span>${esc(o.phone)} · ${identityName(o.identityType)} · ${o.assetCount||0} أصل</span></button>`).join('');if(newBox)newBox.style.display='block';if($('#selectedOwnerInfo'))$('#selectedOwnerInfo').innerHTML=xs.length?'<div class="muted">اختر المالك الصحيح من الاقتراحات أعلاه.</div>':'<div class="muted">لا يوجد مالك مطابق. أكمل بيانات المالك الجديد ثم احفظ الأصل.</div>'}
function setOwnerFieldsEditable(editable){['noi','non','nop'].forEach(id=>{const el=$('#'+id);if(el)el.disabled=!editable})}function selectOwner(o){$('#ao').value=o.id;$('#aoSearch').value=o.name;$('#ownerSuggestions').innerHTML='';if($('#noi'))$('#noi').value=o.identityType||'NATIONAL_ID';if($('#non'))$('#non').value=o.identityNumber||'';if($('#nop'))$('#nop').value=o.phone||'';setOwnerFieldsEditable(false);if($('#newOwnerFields'))$('#newOwnerFields').style.display='block';renderSelectedOwner(o)}

function ownerForm(o={}){if(!o.id&&window.__assetEdit&&document.querySelector('#ownerPicker'))window.__returnToAsset=true;modal(`<h3>${o.id?'تعديل بيانات المالك':'إضافة مالك جديد'}</h3><div class="field"><label>اسم المالك</label><input id="oname" class="input" value="${esc(o.name||'')}"></div><div class="two"><div class="field"><label>نوع الهوية</label><select id="oit" class="select"><option value="NATIONAL_ID" ${o.identityType==='NATIONAL_ID'?'selected':''}>هوية وطنية</option><option value="PERSONAL_ID" ${o.identityType==='PERSONAL_ID'?'selected':''}>بطاقة شخصية</option><option value="RESIDENCY_ID" ${o.identityType==='RESIDENCY_ID'?'selected':''}>هوية مقيم</option><option value="PASSPORT" ${o.identityType==='PASSPORT'?'selected':''}>جواز سفر</option><option value="OTHER" ${o.identityType==='OTHER'?'selected':''}>هوية أخرى</option></select></div><div class="field"><label>رقم الهوية</label><input id="oin" class="input" value="${esc(o.identityNumber||'')}"></div></div><div class="field"><label>رقم الهاتف</label><input id="oph" class="input" value="${esc(o.phone||'')}"></div><div class="two"><input id="oem" class="input" placeholder="البريد الإلكتروني (اختياري)" value="${esc(o.email||'')}"><input id="oad" class="input" placeholder="العنوان (اختياري)" value="${esc(o.address||'')}"></div><button class="btn primary" onclick="saveOwner('${o.id||''}')">حفظ المالك</button>`)}
async function saveOwner(id){try{const o=await api(id?'/api/admin/owners/'+id:'/api/admin/owners',{method:id?'PUT':'POST',body:JSON.stringify({name:$('#oname').value,identityType:$('#oit').value,identityNumber:$('#oin').value,phone:$('#oph').value,email:$('#oem').value,address:$('#oad').value})});closeModal();if(window.__returnToAsset){window.__returnToAsset=false;assetForm({...window.__assetEdit,ownerId:o.id,ownerType:'OWNER'})}else dashboard('owners')}catch(e){alert(e.message)}}
function updatePurposeCards(){const c=state.cats.find(x=>x.id===$('#ag')?.value);if(!c)return;const allowed={SALE:!!c.allowSale,RENT:!!c.allowRent,STORAGE:!!c.allowStorage,SALE_RENT:!!c.allowSale&&!!c.allowRent};document.querySelectorAll('.purpose-card').forEach(x=>{const ok=allowed[x.dataset.purpose];x.disabled=!ok;x.classList.toggle('disabled',!ok);});const current=$('#ap')?.value;if(current&&!allowed[current]){const next=['SALE','RENT','STORAGE','SALE_RENT'].find(x=>allowed[x]);if(next)selectAssetPurpose(next);}}
function selectAssetPurpose(p){$('#ap').value=p;document.querySelectorAll('.purpose-card').forEach(x=>x.classList.toggle('selected',x.dataset.purpose===p));updateAssetPriceFields();}
function toggleOwnerChoice(){const c=$('#aoy'),p=$('#ownerPicker');if(!c||!p)return;p.style.display=c.checked?'none':'block';if(c.checked){$('#ao').value='';if($('#aoSearch'))$('#aoSearch').value='';if($('#selectedOwnerInfo'))$('#selectedOwnerInfo').innerHTML='';}}
function renderDynamicAssetFields(values={}){const c=state.cats.find(x=>x.id===$('#ag')?.value)||{};let fields=Array.isArray(c.fields)&&c.fields.length?c.fields:[{key:'assetType',label:'نوع الأصل / المعدة',type:'text'},{key:'model',label:'الموديل',type:'text'}];fields=fields.filter(f=>f.key!=='year');if(c.slug==='vehicles'){fields=[{key:'vehicleType',label:'الشركة / النوع',type:'select',options:(window.__vehicleTypes||[]).map(v=>({value:v.id,label:v.name})).concat([{value:'OTHER',label:'أخرى'}])},{key:'model',label:'الموديل',type:'text'},{key:'color',label:'اللون',type:'text'},{key:'plateNumber',label:'رقم اللوحة',type:'text'},{key:'variant',label:'الفئة (اختياري)',type:'text'}];$('#dynamicFields').innerHTML=`<div class="field-section"><h4>بيانات ${esc(c.name||'الأصل')}</h4><div class="two">${fields.map(f=>{const v=values[f.key]??'';if(f.type==='select')return `<div class="field"><label>${esc(f.label)}</label><select class="select dynamic-field" data-key="${esc(f.key)}" onchange="updateGeneratedTitle();toggleVehicleOther()"><option value="">اختر</option>${(f.options||[]).map(o=>{const val=typeof o==='string'?o:o.value,lab=typeof o==='string'?o:o.label;return `<option value="${esc(val)}" ${String(v)===String(val)?'selected':''}>${esc(lab)}</option>`}).join('')}</select>${f.key==='vehicleType'?`<input id="vehicleTypeOther" class="input" placeholder="اكتب نوع المركبة" value="${esc(values.vehicleTypeOther||'')}" style="display:${v==='OTHER'?'block':'none'};margin-top:6px" oninput="updateGeneratedTitle()">`:''}</div>`;return `<div class="field"><label>${esc(f.label)}</label><input class="input dynamic-field" data-key="${esc(f.key)}" type="text" value="${esc(v)}" oninput="updateGeneratedTitle()"></div>`}).join('')}</div></div>`;updateGeneratedTitle();}else{$('#dynamicFields').innerHTML=`<div class="field-section"><h4>بيانات ${esc(c.name||'الأصل')}</h4><div class="two">${fields.map(f=>`<div class="field"><label>${esc(f.label)}</label><input class="input dynamic-field" data-key="${esc(f.key)}" type="text" value="${esc(values[f.key]??'')}" oninput="updateGeneratedTitle()"></div>`).join('')}</div></div>`;updateGeneratedTitle();}}

function toggleVehicleOther(){const x=$('.dynamic-field[data-key="vehicleType"]'),o=$('#vehicleTypeOther');if(o)o.style.display=x?.value==='OTHER'?'block':'none';}
function updateGeneratedTitle(){const c=state.cats.find(x=>x.id===$('#ag')?.value);if(!c)return;const cf={};document.querySelectorAll('.dynamic-field').forEach(x=>cf[x.dataset.key]=x.value);if($('#vehicleTypeOther'))cf.vehicleTypeOther=$('#vehicleTypeOther').value;const parts=c.slug==='vehicles'?[cf.vehicleType==='OTHER'?cf.vehicleTypeOther:(window.__vehicleTypes||[]).find(v=>v.id===cf.vehicleType)?.name,cf.model]:[cf.assetType,cf.equipmentType,cf.boxType,cf.model];if($('#at'))$('#at').value=parts.filter(x=>String(x||'').trim()).join(' ').trim()||c.name||'أصل جديد';}

function updateAssetPriceFields(){const p=$('#ap')?.value||'SALE',a=window.__assetEdit||{};let h='';if(p==='SALE')h=`<div class="field"><label>طريقة تحديد سعر البيع</label><select id="aspMode" class="select" onchange="updateSalePriceMode()"><option value="FIXED" ${a.salePriceMode!=='ON_BID'?'selected':''}>سعر محدد</option><option value="ON_BID" ${a.salePriceMode==='ON_BID'?'selected':''}>على السوم</option></select></div><div class="two"><div class="field"><label>سعر البيع المطلوب</label><input id="asp" class="input" type="number" min="0" value="${esc(a.salePrice??'')}" ${a.salePriceMode==='ON_BID'?'disabled':''} placeholder="${a.salePriceMode==='ON_BID'?'على السوم لا يحتاج مبلغًا':'أدخل المبلغ'}"></div><div class="field"><label>السوم الحالي <span class="muted">(اختياري)</span></label><input id="acb" class="input" type="number" min="0" value="${esc(a.currentBid??'')}" placeholder="اتركه فارغًا إذا لم يوجد سوم"></div></div><div class="field-section parking-fee-section"><h4>رسوم الموقف</h4><label class="checkline"><input id="aparkingEnabled" type="checkbox" ${a.parkingFeeEnabled?'checked':''} onchange="toggleParkingFee()"> هذا الأصل عليه رسوم موقف</label><div class="field" id="parkingFeeField" style="display:${a.parkingFeeEnabled?'block':'none'}"><label>مبلغ الموقف (${esc(state.settings?.currency||'SAR')})</label><input id="aparkingFee" class="input" type="number" min="0" step="0.01" value="${esc(a.parkingFee??'')}" placeholder="أدخل مبلغ الموقف"></div><small class="muted">اختياري، ولا يُضاف إلا إذا فعّلت الخيار وأدخلت المبلغ.</small></div>`;if(p==='RENT')h=`<div class="two"><div class="field"><label>سعر الإيجار</label><input id="arp" class="input" type="number" value="${esc(a.rentPrice??'')}"></div><div class="field"><label>وحدة الإيجار</label><select id="aru" class="select"><option value="يوم">يومي</option><option value="أسبوع">أسبوعي</option><option value="شهر">شهري</option></select></div></div><div class="field"><label>رسوم توقيف الحوش اليومية</label><input id="adf" class="input" type="number" value="${esc(a.dailyStorageFee??state.settings.storageDefaultRate)}"></div>`;if(p==='SALE_RENT')h=`<div class="field"><label>طريقة تحديد سعر البيع</label><select id="aspMode" class="select" onchange="updateSalePriceMode()"><option value="FIXED" ${a.salePriceMode!=='ON_BID'?'selected':''}>سعر محدد</option><option value="ON_BID" ${a.salePriceMode==='ON_BID'?'selected':''}>على السوم</option></select></div><div class="two"><div class="field"><label>سعر البيع المطلوب</label><input id="asp" class="input" type="number" min="0" value="${esc(a.salePrice??'')}" ${a.salePriceMode==='ON_BID'?'disabled':''} placeholder="${a.salePriceMode==='ON_BID'?'على السوم لا يحتاج مبلغًا':'أدخل المبلغ'}"></div><div class="field"><label>السوم الحالي <span class="muted">(اختياري)</span></label><input id="acb" class="input" type="number" min="0" value="${esc(a.currentBid??'')}" placeholder="اتركه فارغًا إذا لم يوجد سوم"></div></div><div class="field-section parking-fee-section"><h4>رسوم الموقف</h4><label class="checkline"><input id="aparkingEnabled" type="checkbox" ${a.parkingFeeEnabled?'checked':''} onchange="toggleParkingFee()"> هذا الأصل عليه رسوم موقف</label><div class="field" id="parkingFeeField" style="display:${a.parkingFeeEnabled?'block':'none'}"><label>مبلغ الموقف (${esc(state.settings?.currency||'SAR')})</label><input id="aparkingFee" class="input" type="number" min="0" step="0.01" value="${esc(a.parkingFee??'')}" placeholder="أدخل مبلغ الموقف"></div><small class="muted">اختياري، ولا يُضاف إلا إذا فعّلت الخيار وأدخلت المبلغ.</small></div><div class="two"><div class="field"><label>سعر الإيجار</label><input id="arp" class="input" type="number" value="${esc(a.rentPrice??'')}"></div><div class="field"><label>وحدة الإيجار</label><select id="aru" class="select"><option value="يوم">يومي</option><option value="أسبوع">أسبوعي</option><option value="شهر">شهري</option></select></div></div><div class="field"><label>رسوم توقيف الحوش اليومية</label><input id="adf" class="input" type="number" value="${esc(a.dailyStorageFee??state.settings.storageDefaultRate)}"></div>`;if(p==='STORAGE')h=`<div class="field"><label>سعر التوقيف اليومي</label><input id="adf" class="input" type="number" value="${esc(a.dailyStorageFee??state.settings.storageDefaultRate)}"></div>`;$('#priceFields').innerHTML=h;if($('#aru'))$('#aru').value=a.rentUnit||'يوم';toggleParkingFee();}
function toggleParkingFee(){const enabled=!!$('#aparkingEnabled')?.checked,field=$('#parkingFeeField'),input=$('#aparkingFee');if(field)field.style.display=enabled?'block':'none';if(input){input.disabled=!enabled;if(!enabled)input.value='';}}
function updateSalePriceMode(){const mode=$('#aspMode')?.value||'FIXED',input=$('#asp');if(!input)return;input.disabled=mode==='ON_BID';if(mode==='ON_BID'){input.value='';input.placeholder='على السوم لا يحتاج مبلغًا'}else input.placeholder='أدخل المبلغ';}
