async function saveAsset(id){if(window.__assetSaveBusy)return;const btn=$('#assetSaveBtn');window.__assetSaveBusy=true;if(btn){btn.disabled=true;btn.textContent=id?'جارٍ حفظ التعديلات...':'جارٍ إضافة الأصل...';}try{const ownerYard=$('#aoy')?.checked,purpose=$('#ap').value,customFields={};document.querySelectorAll('.dynamic-field').forEach(x=>customFields[x.dataset.key]=x.value);if($('#vehicleTypeOther'))customFields.vehicleTypeOther=$('#vehicleTypeOther').value;let ownerId=$('#ao').value,ownerType=ownerYard?'USER':'OWNER';const ownerData=!ownerYard&&!ownerId?{name:$('#aoSearch').value.trim(),phone:$('#nop')?.value.trim(),identityNumber:$('#non')?.value.trim(),identityType:$('#noi')?.value||'NATIONAL_ID',clientRequestId:window.__ownerRequestId||(window.__ownerRequestId=crypto.randomUUID())}:null;if(!ownerYard&&!ownerId&&(!ownerData.name||!ownerData.phone||!ownerData.identityNumber))throw Error('أدخل اسم المالك ورقم الهاتف ورقم الهوية، أو اختر مالكًا موجودًا من الاقتراحات');const b={categoryId:$('#ag').value,ownerId,ownerType,yardId:state.yards[0]?.id||'demo-yard',purpose,status:id?($('#as')?.value||'ACTIVE'):'ACTIVE',salePriceMode:($('#aspMode')?.value==='ON_BID'&&['SALE','SALE_RENT'].includes(purpose))?'ON_BID':'FIXED',salePrice:(($('#aspMode')?.value==='ON_BID'&&['SALE','SALE_RENT'].includes(purpose))?null:($('#asp')?.value||null)),currentBid:$('#acb')?.value||null,rentPrice:$('#arp')?.value||null,rentUnit:$('#aru')?.value||null,dailyStorageFee:$('#adf')?.value||0,parkingFeeEnabled:!!$('#aparkingEnabled')?.checked,parkingFee:$('#aparkingEnabled')?.checked?($('#aparkingFee')?.value||0):0,make:'',model:customFields.model||'',year:null,color:customFields.color||'',variant:customFields.variant||'',plateNumber:customFields.plateNumber||'',locationCode:$('#al').value,entryAt:$('#ae')?.value?new Date($('#ae').value).toISOString():null,description:$('#ad').value,entryNotes:$('#an').value,customFields,promoActive:!!$('#promoActive')?.checked,promoTitle:$('#promoTitle')?.value||'',promoDescription:$('#promoDescription')?.value||'',promoPrice:$('#promoPrice')?.value||null,promoDurationHours:Number($('#promoDurationHours')?.value||24)};if(purpose==='SALE'){b.rentPrice=null;b.rentUnit=null;b.dailyStorageFee=0}if(!['SALE','SALE_RENT'].includes(purpose)){b.parkingFeeEnabled=false;b.parkingFee=0}if(purpose==='STORAGE'){b.salePrice=null;b.rentPrice=null;b.rentUnit=null}const imageFiles=[...($('#ai')?.files||[]),...($('#aiCamera')?.files||[])];const images=[];for(const f of imageFiles){const data=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(f)});images.push({dataUrl:data,filename:f.name})}if(id){if(!b.ownerId)throw Error('اختر مالكًا موجودًا عند تعديل أصل');const saved=await api('/api/admin/assets/'+id,{method:'PUT',body:JSON.stringify(b)});for(const x of images)await api('/api/admin/assets/'+saved.id+'/images',{method:'POST',body:JSON.stringify(x)});closeModal();window.__assetRequestId=null;window.__ownerRequestId=null;await dashboard('assets');alert('تم حفظ التعديلات بنجاح');return}const item={id:window.__assetRequestId||(window.__assetRequestId=crypto.randomUUID()),owner:ownerData,asset:{...b,clientRequestId:window.__assetRequestId},images,createdOfflineAt:new Date().toISOString()};try{const saved=await api('/api/admin/offline/intake',{method:'POST',body:JSON.stringify(item)});closeModal();window.__assetRequestId=null;window.__ownerRequestId=null;await dashboard('assets');assetReceiptActions(saved)}catch(e){if(!isNetworkError(e))throw e;await queueIntake(item);closeModal();window.__assetRequestId=null;window.__ownerRequestId=null;alert('تم حفظ الأصل والمالك على الجهاز بدون إنترنت. سيُرسل تلقائيًا عند عودة الاتصال.');await dashboard('assets').catch(()=>{})}}catch(e){window.__assetSaveBusy=false;if(btn){btn.disabled=false;btn.textContent=id?'حفظ التعديلات':'＋ إضافة الأصل وحفظ';}alert(e.message)}finally{window.__assetSaveBusy=false}}

