async function reverseFinance(id){const reason=prompt('سبب عكس الحركة المالية؟ سيتم إنشاء حركة عكسية مع الاحتفاظ بالحركة الأصلية.');if(reason===null)return;if(reason.trim().length<5){alert('اكتب سببًا واضحًا من 5 أحرف على الأقل');return}if(!confirm('تأكيد إنشاء حركة عكسية؟ لن تُحذف الحركة الأصلية.'))return;try{await api(`/api/admin/transactions/${id}/reverse`,{method:'POST',body:JSON.stringify({reason:reason.trim()})});alert('تم تسجيل حركة العكس مع حفظ أثر التدقيق');dashboard('finance')}catch(e){alert(e.message)}}
function financeForm(){const defaultDate=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);modal(`<h3>حركة مالية</h3><div class="two"><select id="ft" class="select"><option value="INCOME">دخل</option><option value="EXPENSE">مصروف</option></select><input id="fa" class="input" type="number" min="0.01" step="0.01" placeholder="المبلغ"></div><div class="field"><label for="fdate">تاريخ ووقت الحركة</label><input id="fdate" class="input" type="datetime-local" value="${defaultDate}" required><small class="muted">يُحدد تلقائيًا بالوقت الحالي، ويمكن تغييره لتسجيل حركة سابقة، مع حفظ وقت التسجيل الفعلي منفصلًا.</small></div><div class="field"><input id="fc" class="input" placeholder="التصنيف"></div><div class="field"><input id="fr" class="input" placeholder="المرجع"></div><div class="field"><textarea id="fd" class="input" placeholder="الوصف"></textarea></div><button class="btn primary" onclick="saveFinance()">حفظ</button>`)}async function saveFinance(){const dateValue=$('#fdate')?.value;if(!dateValue){alert('حدد تاريخ ووقت الحركة');return}const createdAt=new Date(dateValue);if(Number.isNaN(createdAt.getTime())){alert('تاريخ ووقت الحركة غير صحيح');return}try{await api('/api/admin/transactions',{method:'POST',body:JSON.stringify({type:$('#ft').value,amount:$('#fa').value,category:$('#fc').value,reference:$('#fr').value,description:$('#fd').value,createdAt:createdAt.toISOString()})});closeModal();dashboard('finance')}catch(e){alert(e.message)}}
function orderForm(){modal(`<h3>تسجيل طلب</h3><div class="two"><input id="ocn" class="input" placeholder="اسم العميل"><input id="ocp" class="input" placeholder="الجوال"></div><div class="two"><select id="oct" class="select"><option value="GENERAL">طلب عام</option><option value="BUY">شراء</option><option value="RENT">إيجار</option><option value="SERVICE">خدمة</option><option value="OTHER">أخرى</option></select><input id="oca" class="input" type="number" placeholder="المبلغ المتوقع (اختياري)"></div><textarea id="ocd" class="input" placeholder="تفاصيل الطلب"></textarea><textarea id="ocn2" class="input" placeholder="ملاحظات"></textarea><button id="orderSaveBtn" class="btn primary" onclick="saveOrder()">حفظ الطلب</button>`)}async function saveOrder(){if(window.__orderBusy)return;window.__orderBusy=true;const btn=$('#orderSaveBtn');if(btn)btn.disabled=true;try{const clientRequestId=window.__orderRequestId||(window.__orderRequestId=crypto.randomUUID());await api('/api/admin/orders',{method:'POST',body:JSON.stringify({customerName:$('#ocn').value,phone:$('#ocp').value,type:$('#oct').value,amount:$('#oca').value,description:$('#ocd').value,notes:$('#ocn2').value,clientRequestId})});window.__orderRequestId=null;closeModal();await dashboard('orders')}catch(e){alert(e.message)}finally{window.__orderBusy=false;if(btn)btn.disabled=false}}async function orderStatus(id,status){try{await api('/api/admin/orders/'+id,{method:'PUT',body:JSON.stringify({status})});await dashboard('orders')}catch(e){alert(e.message)}}
async function recordInvoicePayment(id,balance){if(!Number.isFinite(balance)||balance<=0){alert('لا يوجد مبلغ متبقٍ على هذه الفاتورة');return}const raw=prompt(`أدخل مبلغ الدفعة الجديدة. المتبقي: ${balance}`,'');if(raw===null)return;const amount=Number(raw);if(!Number.isFinite(amount)||amount<=0||amount>balance){alert('مبلغ الدفعة غير صحيح أو يتجاوز المتبقي');return}if(!confirm(`تسجيل دفعة بمبلغ ${amount}؟ سيتم حفظها كحركة مالية مستقلة.`))return;try{await api(`/api/admin/invoices/${id}/payments`,{method:'POST',body:JSON.stringify({amount,clientRequestId:crypto.randomUUID()})});await dashboard('invoices');alert('تم تسجيل الدفعة وتحديث رصيد الفاتورة.')}catch(e){alert(e.message)}}
async function refundInvoice(id,paid){if(Number(paid)<=0){alert('لا يوجد مبلغ مدفوع قابل للاسترداد');return}const amount=prompt(`المبلغ المراد استرداده (الحد الأقصى ${paid})`,'');if(amount===null)return;const reason=prompt('سبب الاسترداد (5 أحرف على الأقل):','');if(reason===null)return;try{await api(`/api/admin/invoices/${id}/refunds`,{method:'POST',body:JSON.stringify({amount:Number(amount),reason,clientRequestId:crypto.randomUUID()})});await dashboard('invoices')}catch(e){alert(e.message)}}
async function adjustInvoicePaid(id,current,total){const raw=prompt(`أدخل إجمالي المبلغ المدفوع الصحيح (من 0 إلى ${total}). إذا خُفّض المبلغ سيُسجل فرق التسوية كحركة مصروف مع توثيق التعديل.`,String(current));if(raw===null)return;const paid=Number(raw);if(!Number.isFinite(paid)||paid<0||paid>total){alert('المبلغ المدفوع غير صحيح');return}if(!confirm('سيُسجل فرق التعديل كحركة مالية جديدة مع حفظ أثر التدقيق. متابعة؟'))return;try{await api(`/api/admin/invoices/${id}`,{method:'PUT',body:JSON.stringify({paid})});await dashboard('invoices')}catch(e){alert(e.message)}}
function invoiceForm(){modal(`<h3>إصدار فاتورة</h3><p class="muted">الفاتورة لإثبات مبلغ مستحق على عميل مقابل بيع أو إيجار أو خدمة. أما المشتريات والمقاضي والكفرات ونحوها فتسجل كمصروف في المالية.</p><div class="two"><input id="ipn" class="input" placeholder="اسم العميل / الطرف *"><input id="ipp" class="input" placeholder="الجوال"></div><div class="two"><select id="itype" class="select"><option value="SALE">بيع</option><option value="RENT">إيجار</option><option value="SERVICE">خدمة</option><option value="STORAGE">تخزين / توقيف</option><option value="OTHER">أخرى</option></select><input id="isub" class="input" type="number" min="0" placeholder="الإجمالي قبل الخصم والضريبة"></div><div class="two"><input id="idis" class="input" type="number" placeholder="الخصم"><input id="itax" class="input" type="number" placeholder="الضريبة"></div><div class="two"><input id="ipaid" class="input" type="number" placeholder="المدفوع"><input id="iasset" class="input" placeholder="كود الأصل (اختياري)"></div><textarea id="inotes" class="input" placeholder="بيان الفاتورة / التفاصيل"></textarea><br><br><button class="btn primary" onclick="saveInvoice()">إصدار الفاتورة</button>`)}async function saveInvoice(){if(window.__invoiceBusy)return;window.__invoiceBusy=true;try{await api('/api/admin/invoices',{method:'POST',body:JSON.stringify({type:$('#itype').value,partyName:$('#ipn').value,partyPhone:$('#ipp').value,subtotal:$('#isub').value,discount:$('#idis').value,tax:$('#itax').value,paid:$('#ipaid').value,assetId:$('#iasset').value||null,notes:$('#inotes').value})});closeModal();await dashboard('invoices')}catch(e){alert(e.message)}finally{window.__invoiceBusy=false}}
function contractTypeArabic(type){return ({SALE:'اتفاقية بيع',RENT:'اتفاقية إيجار',STORAGE:'اتفاقية تخزين أصل',BROKERAGE_SALE:'اتفاقية وساطة بيع'})[type]||'اتفاقية'}
