async function approveContract(id){if(!confirm('هل راجعت بيانات الطرفين والمبلغ والصور والشروط وتريد اعتماد العقد؟ بعد الاعتماد لن يمكن تعديله مباشرة.'))return;try{await api('/api/admin/contracts/'+id,{method:'PUT',body:JSON.stringify({status:'APPROVED'})});await dashboard('contracts');alert('تم اعتماد العقد وتوثيق العملية في سجل التدقيق.')}catch(e){alert(e.message)}}
const IDENTITY_IMAGE_MAX_BYTES=950_000;
function decodeUploadImage(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file);const done=(fn,v)=>{URL.revokeObjectURL(url);fn(v)};if(typeof createImageBitmap==='function'){createImageBitmap(file).then(bitmap=>done(resolve,{source:bitmap,width:bitmap.width,height:bitmap.height,close:()=>bitmap.close()})).catch(()=>{const img=new Image();img.onload=()=>done(resolve,{source:img,width:img.naturalWidth,height:img.naturalHeight});img.onerror=()=>done(reject,Error('تعذر فتح الصورة؛ جرّب اختيار صورة JPG أو PNG من الاستوديو'));img.src=url})}else{const img=new Image();img.onload=()=>done(resolve,{source:img,width:img.naturalWidth,height:img.naturalHeight});img.onerror=()=>done(reject,Error('تعذر فتح الصورة؛ جرّب اختيار صورة JPG أو PNG من الاستوديو'));img.src=url}})}
async function compressIdentityImage(file){if(!file)return '';if(!String(file.type||'').startsWith('image/'))throw Error('الملف المختار ليس صورة');const decoded=await decodeUploadImage(file);try{let width=decoded.width,height=decoded.height;if(!width||!height)throw Error('أبعاد الصورة غير صالحة');const initialScale=Math.min(1,2200/Math.max(width,height));width=Math.max(1,Math.round(width*initialScale));height=Math.max(1,Math.round(height*initialScale));const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');if(!ctx)throw Error('المتصفح لا يدعم ضغط الصور');let blob=null;for(let dimensionTry=0;dimensionTry<10;dimensionTry++){canvas.width=width;canvas.height=height;ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height);ctx.drawImage(decoded.source,0,0,width,height);for(const quality of [.88,.80,.72,.64,.56,.48]){blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',quality));if(blob&&blob.size<=IDENTITY_IMAGE_MAX_BYTES)break}if(blob&&blob.size<=IDENTITY_IMAGE_MAX_BYTES)break;width=Math.max(1,Math.round(width*.82));height=Math.max(1,Math.round(height*.82))}if(!blob||blob.size>IDENTITY_IMAGE_MAX_BYTES)throw Error('تعذر ضغط الصورة إلى أقل من 1 ميغابايت؛ جرّب صورة أخرى');return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=()=>reject(Error('تعذرت قراءة الصورة بعد ضغطها'));reader.readAsDataURL(blob)})}finally{decoded.close?.()}}
function readIdentityImage(file){return compressIdentityImage(file)}
function selectedIdentityImage(galleryId,cameraId){return $('#'+cameraId)?.files?.[0]||$('#'+galleryId)?.files?.[0]||null}
function wireIdentityImagePickers(galleryId,cameraId){const gallery=$('#'+galleryId),camera=$('#'+cameraId);if(gallery&&camera){gallery.addEventListener('change',()=>{if(gallery.files?.length)camera.value=''});camera.addEventListener('change',()=>{if(camera.files?.length)gallery.value=''})}}
async function contractForm(){const [xs,reservations]=await Promise.all([api('/api/admin/assets'),api('/api/admin/reservations')]);if(!xs.length){alert('أضف أصلًا أولًا قبل إنشاء الاتفاقية');return}modal(`<h3>إنشاء اتفاقية</h3><div class="field"><label>نوع الاتفاقية</label><select id="ctkind" class="select" onchange="contractFields()"><option value="SALE">اتفاقية بيع</option><option value="RENT">اتفاقية إيجار</option><option value="STORAGE">اتفاقية تخزين أصل</option><option value="BROKERAGE_SALE">اتفاقية وساطة بيع</option></select></div><div class="field"><label>ربط بحجز مؤكد (اختياري)</label><select id="ctreservation" class="select" onchange="linkReservationToContract()"><option value="">بدون ربط بحجز</option>${reservations.filter(r=>r.status==='CONFIRMED').map(r=>`<option value="${r.id}" data-asset="${r.assetId}" data-kind="${r.reservationType==='RENT'?'RENT':'SALE'}" data-name="${esc(r.customer?.name||'')}" data-phone="${esc(r.customer?.phone||'')}" data-from="${esc(r.fromAt||'')}" data-to="${esc(r.toAt||'')}">${esc(r.code||r.id)} — ${esc(r.asset?.title||'أصل')} — ${esc(r.customer?.name||'عميل')}</option>`).join('')}</select><small class="muted">عند اختيار الحجز، يربط النظام العقد بالأصل والعميل نفسيهما.</small></div><div class="field"><label>الأصل</label><select id="cta" class="select">${xs.map(a=>`<option value="${a.id}" data-title="${esc(a.title)}" data-code="${esc(a.code)}">${esc(a.title)} — ${a.code}</option>`).join('')}</select></div><div class="field"><label id="ctpartylabel">اسم المشتري</label><input id="ctp" class="input" placeholder="الاسم الكامل" required></div><div class="two"><div class="field"><label>رقم هاتف الطرف الآخر</label><input id="ctph" class="input" type="tel" placeholder="رقم الهاتف" required></div><div class="field"><label>نوع الهوية</label><select id="ctidtype" class="select"><option value="">غير محدد</option><option>هوية وطنية</option><option>بطاقة شخصية</option><option>هوية مقيم</option><option>جواز سفر</option><option>أخرى</option></select></div><div class="field"><label>رقم الهوية</label><input id="ctidnum" class="input" placeholder="رقم الهوية"></div></div><div class="panel"><h4>صورة وثيقة البيع</h4><p class="muted">أرفق مستند البيع إن كان منفصلًا عن وثائق الهوية. تُضغط الصورة تلقائيًا قبل الحفظ.</p><div class="image-upload-actions"><label class="btn primary image-pick"><span>📁 اختيار من الاستوديو / الملفات</span><input id="ctsaleimg" type="file" accept="image/*"></label><label class="btn success image-pick"><span>📷 تصوير وثيقة البيع</span><input id="ctsaleimgCamera" type="file" accept="image/*" capture="environment"></label></div></div><div class="panel"><h4>صورة ملف الأصل / مستند الملكية</h4><p class="muted">يمكنك تصوير ملف الأصل أو اختيار صورة من الاستوديو، وسيُضغط الملف تلقائيًا.</p><div class="image-upload-actions"><label class="btn primary image-pick"><span>📁 اختيار من الاستوديو / الملفات</span><input id="ctassetdocimg" type="file" accept="image/*"></label><label class="btn success image-pick"><span>📷 تصوير ملف الأصل</span><input id="ctassetdocimgCamera" type="file" accept="image/*" capture="environment"></label></div></div><div class="panel"><h4>صورة وثيقة الطرف الآخر (المشتري)</h4><p class="muted">اختر التصوير بالكاميرا أو صورة موجودة في الاستوديو. تُضغط الصورة تلقائيًا قبل الحفظ لتصبح أقل من 1 ميغابايت.</p><div class="image-upload-actions"><label class="btn primary image-pick"><span>📁 اختيار من الاستوديو / الملفات</span><input id="ctpartyimg" type="file" accept="image/*"></label><label class="btn success image-pick"><span>📷 تصوير وثيقة المشتري</span><input id="ctpartyimgCamera" type="file" accept="image/*" capture="environment"></label></div><small class="muted">تُحفظ الصورة ضمن العقد ولا تُعرض في صفحة الأصل العامة.</small></div><div class="panel"><h4>صورة وثيقة البائع / ملف الأصل</h4><p class="muted">يمكنك التصوير مباشرة أو اختيار صورة الوثيقة من الاستوديو؛ الضغط يتم تلقائيًا.</p><div class="image-upload-actions"><label class="btn primary image-pick"><span>📁 اختيار من الاستوديو / الملفات</span><input id="ctsellerimg" type="file" accept="image/*"></label><label class="btn success image-pick"><span>📷 تصوير الوثيقة</span><input id="ctsellerimgCamera" type="file" accept="image/*" capture="environment"></label></div><small class="muted">تُحفظ الصورة ضمن العقد ولا تُعرض في صفحة الأصل العامة.</small></div><div id="cttypefields"></div><div class="two"><div class="field"><label id="ctamountlabel">السعر المتفق عليه</label><input id="ctam" class="input" type="number" min="0" step="0.01" placeholder="المبلغ" value="0"></div><div class="field"><label>العملة</label><input class="input" value="${esc(state.settings?.currency||'SAR')}" disabled></div></div><div class="field"><label>الشروط الإضافية</label><textarea id="ctterms" class="input" rows="3" placeholder="تُضاف الشروط المتفق عليها"></textarea></div><p class="muted">سيظهر رقم هاتف البائع/مالك الأصل من بياناته المسجلة، ورقم الطرف الآخر من الحقول أعلاه. راجع الاتفاقية قبل طباعتها أو توقيعها.</p><button class="btn primary" onclick="saveContract()">حفظ الاتفاقية</button>`);wireIdentityImagePickers('ctpartyimg','ctpartyimgCamera');wireIdentityImagePickers('ctsellerimg','ctsellerimgCamera');wireIdentityImagePickers('ctsaleimg','ctsaleimgCamera');wireIdentityImagePickers('ctassetdocimg','ctassetdocimgCamera');contractFields()}
function linkReservationToContract(){const sel=$('#ctreservation'),opt=sel?.selectedOptions?.[0];if(!sel?.value||!opt)return;const assetId=opt.dataset.asset||'',kind=opt.dataset.kind||'SALE';if($('#cta')&&Array.from($('#cta').options).some(x=>x.value===assetId))$('#cta').value=assetId;if($('#ctkind'))$('#ctkind').value=kind;contractFields();if($('#ctp'))$('#ctp').value=opt.dataset.name||'';if($('#ctph'))$('#ctph').value=opt.dataset.phone||'';if(kind==='RENT'){if($('#ctstart'))$('#ctstart').value=(opt.dataset.from||'').slice(0,10);if($('#ctend'))$('#ctend').value=(opt.dataset.to||'').slice(0,10)}}
function contractFields(){const type=$('#ctkind')?.value;if(!type)return;$('#ctpartylabel').textContent=type==='RENT'?'اسم المستأجر':type==='STORAGE'?'اسم ممثل الحوش / المستلم':type==='BROKERAGE_SALE'?'اسم الطرف المتعاقد':'اسم المشتري';$('#ctamountlabel').textContent=type==='RENT'?'قيمة الإيجار الإجمالية':type==='STORAGE'?'رسوم التخزين المتفق عليها':'السعر المتفق عليه';$('#cttypefields').innerHTML=type==='RENT'?`<div class="two"><div class="field"><label>وحدة الإيجار</label><select id="ctrentunit" class="select"><option>يوم</option><option>أسبوع</option><option>شهر</option><option>سنة</option></select></div><div class="field"><label>بداية الإيجار</label><input id="ctstart" class="input" type="date"></div><div class="field"><label>نهاية الإيجار</label><input id="ctend" class="input" type="date"></div></div>`:type==='STORAGE'?`<div class="field"><label>تاريخ بداية التخزين</label><input id="ctstart" class="input" type="date"></div>`:`<div class="field"><label>ملاحظات الاتفاق</label><input id="ctnote" class="input" placeholder="اختياري"></div>`}
async function saveContract(){try{const type=$('#ctkind').value,amount=Number($('#ctam').value||0),startAt=$('#ctstart')?.value||'',endAt=$('#ctend')?.value||'';if(!$('#ctp').value.trim()||!$('#ctph').value.trim()){alert('أدخل اسم الطرف الآخر ورقم هاتفه');return}if(type==='RENT'&&(!startAt||!endAt||endAt<startAt)){alert('حدد بداية ونهاية صحيحتين للإيجار');return}const [partyIdentityImage,sellerIdentityImage,saleDocumentImage,assetDocumentImage]=await Promise.all([readIdentityImage(selectedIdentityImage('ctpartyimg','ctpartyimgCamera')),readIdentityImage(selectedIdentityImage('ctsellerimg','ctsellerimgCamera')),readIdentityImage(selectedIdentityImage('ctsaleimg','ctsaleimgCamera')),readIdentityImage(selectedIdentityImage('ctassetdocimg','ctassetdocimgCamera'))]);const payload={assetId:$('#cta').value,reservationId:$('#ctreservation')?.value||'',type,partyName:$('#ctp').value.trim(),partyPhone:$('#ctph').value.trim(),partyIdentityType:$('#ctidtype').value,partyIdentityNumber:$('#ctidnum').value.trim(),partyIdentityImage,sellerIdentityImage,saleDocumentImage,assetDocumentImage,amount,rentUnit:$('#ctrentunit')?.value||'',startAt,endAt,terms:[$('#ctterms').value,$('#ctnote')?.value||''].filter(Boolean).join('\n')};const c=await api('/api/admin/contracts',{method:'POST',body:JSON.stringify(payload)});closeModal();dashboard('contracts');alert(`تم حفظ الاتفاقية ${c.code}. افتح معاينة / طباعة لإخراج الورقة.`)}catch(e){alert(e.message)}}
async function createContractPdfFile(paper,code){if(typeof html2canvas!=='function'||!window.jspdf?.jsPDF)throw Error('مكتبات إنشاء PDF غير متاحة. تحقق من اتصال الإنترنت ثم أعد المحاولة.');const canvas=await html2canvas(paper,{scale:2,useCORS:true,backgroundColor:'#ffffff',logging:false});const {jsPDF}=window.jspdf;const pdf=new jsPDF({orientation:'portrait',unit:'mm',format:'a4',compress:true});const pageWidth=210,pageHeight=297,margin=8,usableWidth=pageWidth-margin*2,usableHeight=pageHeight-margin*2;const pxPerMm=canvas.width/usableWidth;const pageCanvasHeight=Math.floor(usableHeight*pxPerMm);let offset=0,page=0;while(offset<canvas.height){const slice=document.createElement('canvas');slice.width=canvas.width;slice.height=Math.min(pageCanvasHeight,canvas.height-offset);const ctx=slice.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,slice.width,slice.height);ctx.drawImage(canvas,0,offset,canvas.width,slice.height,0,0,canvas.width,slice.height);const image=slice.toDataURL('image/jpeg',0.92);if(page>0)pdf.addPage('a4','portrait');const height=slice.height/pxPerMm;pdf.addImage(image,'JPEG',margin,margin,usableWidth,height,undefined,'FAST');offset+=slice.height;page++}const blob=pdf.output('blob');return new File([blob],`Houshak-Contract-${String(code||'contract').replace(/[^a-zA-Z0-9_-]/g,'_')}.pdf`,{type:'application/pdf'})}
async function contractPaper(id){try{const xs=await api('/api/admin/contracts'),c=xs.find(x=>x.id===id);if(!c)throw Error('الاتفاقية غير موجودة');const a=c.assetSnapshot||{},seller=c.sellerName||'________________',buyer=c.partyName||'________________',type=contractTypeArabic(c.type),partyLabel=c.type==='RENT'?'المستأجر':c.type==='STORAGE'?'ممثل الحوش / المستلم':c.type==='BROKERAGE_SALE'?'ممثل الحوش':'المشتري',firstPartyLabel=c.type==='RENT'?'المؤجر':c.type==='STORAGE'?'مالك الأصل':c.type==='BROKERAGE_SALE'?'مالك الأصل / موكل الوساطة':'البائع',date=new Date(c.createdAt).toLocaleDateString('ar-SA'),amount=Number(c.amount||0).toLocaleString('ar-SA'),unit=c.rentUnit?` / ${c.rentUnit}`:'',termText=c.type==='RENT'?`مدة الإيجار من ${c.startAt||'________'} إلى ${c.endAt||'________'}، وفق المبلغ المتفق عليه.`:c.type==='STORAGE'?'اتفق الطرفان على إيداع الأصل للتخزين لدى الحوش وفق الرسوم والشروط الموضحة أدناه.':c.type==='BROKERAGE_SALE'?'اتفق الطرفان على تكليف الحوش بالوساطة وفق الشروط الموضحة أدناه.':'اتفق الطرفان على بيع الأصل الموضح أدناه بالسعر المتفق عليه.';const brand=state.settings||{},brandName=brand.yardName||'حوش أبو مناحي',brandAddress=brand.yardAddress||brand.address||'',brandPhone=brand.yardPhone||brand.phone||'',brandEmail=brand.yardEmail||brand.email||'',brandLogo=brand.yardLogo||brand.logo||'';const w=window.open('','_blank');if(!w)throw Error('اسمح بفتح نافذة المعاينة للطباعة');w.document.write(`<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>${type} ${c.code}</title><style>@page{size:A4;margin:18mm 18mm 18mm 18mm}*{box-sizing:border-box}body{font-family:Tahoma,Arial,sans-serif;color:#222;background:#fff;margin:0}.paper{width:100%;max-width:174mm;min-height:260mm;margin:0 auto;padding:8mm 0;position:relative;direction:rtl;text-align:right;font-style:normal}.brand{display:flex;align-items:center;gap:14px;border-bottom:2px solid #17365d;padding-bottom:10px;margin-bottom:15px}.brand img{max-width:90px;max-height:60px;object-fit:contain}.brand-info{text-align:center;flex:1}.brand-info h2{font-size:18px;margin:0 0 4px}.brand-info p{font-size:11px;margin:3px 0;color:#555}.bism{font-size:16px;text-align:center;margin:0 0 10px}.date{text-align:right;direction:rtl;font-size:13px;margin-bottom:26px;font-style:normal}.title{text-align:center;font-size:22px;font-weight:700;margin:22px 0 28px}.intro{font-size:16px;line-height:2.2;text-align:justify;text-align-last:right;text-justify:inter-word;direction:rtl;font-style:normal}.line{margin:12px 0;font-size:15px;line-height:2;text-align:justify;text-align-last:right;text-justify:inter-word;direction:rtl;font-style:normal;unicode-bidi:plaintext;overflow-wrap:anywhere}.under{display:inline-block;min-width:110px;border-bottom:1px dotted #555;padding:0 4px}.closing{text-align:center;margin:28px 0 34px;font-weight:bold}.signs{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin-top:35px}.sign{border-top:1px solid #888;padding-top:12px;min-height:75px;text-align:center}.foot{margin-top:18px;font-size:12px;color:#555}.identity-documents{margin-top:18px;border-top:1px solid #999;padding-top:10px;break-inside:avoid}.identity-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;align-items:start}.identity-card{border:1px solid #aaa;padding:8px;text-align:center;min-width:0}.identity-card h4{font-size:12px;margin:0 0 6px}.identity-card img{display:block;width:100%;height:105px;object-fit:contain}.identity-placeholder{height:105px;display:flex;align-items:center;justify-content:center;color:#777;font-size:12px}.toolbar{position:fixed;top:8px;left:8px;display:flex;gap:8px}@media print{.toolbar{display:none}.paper{padding:0}}</style></head><body><div class="toolbar"><button onclick="printContractWhenReady()">طباعة</button><button onclick="shareContractPdf()">مشاركة العقد PDF عبر واتساب</button><button onclick="window.close()">إغلاق</button></div><main class="paper"><header class="brand">${brandLogo?`<img src="${escapeHtml(brandLogo)}" alt="شعار الحوش">`:''}<div class="brand-info"><h2>${escapeHtml(brandName)}</h2><p>${escapeHtml(brandAddress)}</p><p>${escapeHtml(brandPhone)}${brandEmail?` — ${escapeHtml(brandEmail)}`:''}</p></div></header><div class="bism">بسم الله الرحمن الرحيم</div><div class="date">التاريخ: ${date} م</div><div class="title">${type}</div><div class="intro">بعون الله تم الاتفاق بين كل من الطرفين التاليين:</div><div class="line">الطرف الأول: ${firstPartyLabel}: <span class="under">${escapeHtml(c.sellerName||seller)}</span> نوع الوثيقة: <span class="under">${escapeHtml(identityTypeArabic(c.sellerIdentityType))}</span> رقم الوثيقة: <span class="under">${escapeHtml(c.sellerIdentityNumber||'________________')}</span></div><div class="line">رقم هاتف البائع: <span class="under">${escapeHtml(c.sellerPhone||'________________')}</span></div><div class="line">الطرف الثاني: ${partyLabel}: <span class="under">${escapeHtml(buyer)}</span> نوع الوثيقة: <span class="under">${escapeHtml(identityTypeArabic(c.partyIdentityType))}</span> رقم الوثيقة: <span class="under">${escapeHtml(c.partyIdentityNumber||'________________')}</span></div><div class="line">رقم هاتف ${partyLabel}: <span class="under">${escapeHtml(c.partyPhone||'________________')}</span></div><div class="line">بيانات الأصل: <span class="under">${escapeHtml(a.title||c.asset?.title||'________________')}</span> كود الأصل: <span class="under">${escapeHtml(a.code||c.asset?.code||'________________')}</span></div><div class="line">${termText}</div><div class="line">المبلغ المتفق عليه: <span class="under">${amount} ${escapeHtml(c.currency||'SAR')}${unit}</span></div>${a.parkingFeeEnabled&&Number(a.parkingFee||0)>0?`<div class="line">رسوم الموقف المتفق عليها: <span class="under">${Number(a.parkingFee).toLocaleString('ar-SA')} ${escapeHtml(c.currency||'SAR')}</span></div>`:''}<div class="line">الشروط والملاحظات: ${escapeHtml(c.terms||'لا توجد شروط إضافية')}</div><div class="closing">وعلى هذا تم الاتفاق بين الطرفين وهما بكامل أهليتهما، والله خير الشاهدين.</div><div class="signs"><div class="sign">البائع / مالك الأصل<br><br>الاسم: ${escapeHtml(c.sellerName||'________________')}<br>التوقيع: __________________</div><div class="sign">${partyLabel}<br><br>الاسم: ${escapeHtml(c.partyName||'________________')}<br>التوقيع: __________________</div></div><div class="identity-documents"><div style="font-weight:bold;text-align:center;margin-bottom:8px">صور وثائق أطراف الاتفاقية</div><div class="identity-grid"><section class="identity-card"><h4>${escapeHtml(identityTypeArabic(c.sellerIdentityType)||'وثيقة البائع / مالك الأصل')}</h4>${c.sellerIdentityImage?`<img src="${c.sellerIdentityImage}" alt="${escapeHtml(c.sellerIdentityType||'صورة وثيقة البائع')}">`:'<div class="identity-placeholder">لم تُرفق صورة وثيقة البائع</div>'}<div style="font-size:11px;margin-top:5px">${escapeHtml(c.sellerName||'البائع / مالك الأصل')}</div></section><section class="identity-card"><h4>${escapeHtml(identityTypeArabic(c.partyIdentityType)||'وثيقة الطرف الآخر')}</h4>${c.partyIdentityImage?`<img src="${c.partyIdentityImage}" alt="${escapeHtml(c.partyIdentityType||'صورة وثيقة الطرف الآخر')}">`:'<div class="identity-placeholder">لم تُرفق صورة وثيقة الطرف الآخر</div>'}<div style="font-size:11px;margin-top:5px">${escapeHtml(c.partyName||'الطرف الآخر')}</div></section></div><div class="identity-grid" style="margin-top:12px"><section class="identity-card"><h4>وثيقة البيع</h4>${c.saleDocumentImage?`<img src="${c.saleDocumentImage}" alt="وثيقة البيع">`:'<div class="identity-placeholder">لم تُرفق وثيقة البيع</div>'}</section><section class="identity-card"><h4>ملف الأصل / مستند الملكية</h4>${c.assetDocumentImage?`<img src="${c.assetDocumentImage}" alt="ملف الأصل">`:'<div class="identity-placeholder">لم يُرفق ملف الأصل</div>'}</section></div></div><div class="foot">رقم الاتفاقية: ${escapeHtml(c.code)} — ${c.approvedAt?`اعتماد إداري بتاريخ ${escapeHtml(new Date(c.approvedAt).toLocaleString('ar-SA'))} بواسطة ${escapeHtml(c.approvedByName||'الإدارة')}`:'مسودة غير معتمدة'} — بصمة لقطة الاعتماد: ${escapeHtml(c.approvalSnapshotHash||'غير متوفرة')} — حُفظت هذه النسخة في نظام حوشك. يُرجى مراجعة البيانات والشروط قبل التوقيع.</div></main><script>function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function waitContractAssets(){const imgs=Array.from(document.images);return Promise.all(imgs.map(img=>img.complete?Promise.resolve():new Promise(resolve=>{img.onload=resolve;img.onerror=resolve}))).then(()=>document.fonts&&document.fonts.ready?document.fonts.ready:Promise.resolve())}function printContractWhenReady(){waitContractAssets().then(()=>setTimeout(()=>window.print(),100))}async function shareContractPdf(){try{await waitContractAssets();if(!window.opener||typeof window.opener.createContractPdfFile!=='function')throw Error('تعذر تجهيز PDF من لوحة الإدارة. حدّث الصفحة ثم حاول مجددًا.');const file=await window.opener.createContractPdfFile(document.querySelector('.paper'),document.title.split(' ').pop());if(navigator.canShare&&navigator.canShare({files:[file]})){await navigator.share({files:[file],title:document.title,text:'عقد البيع/الشراء بصيغة PDF — '+document.title+' — اختر واتساب من قائمة المشاركة لإرسال ملف العقد نفسه.'});return}const url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);alert('تم إنشاء ملف PDF للعقد وحفظه على جهازك. افتح واتساب ثم اختر إرفاق ← مستند وحدد ملف العقد PDF نفسه. لم يتم إرسال رابط بدل الملف.')}catch(e){if(e.name!=='AbortError')alert(e.message||'تعذر مشاركة ملف PDF.')}}</script></body></html>`);w.document.close()}catch(e){alert(e.message)}}
function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function saveRolePermissions(){const role=$('#permissionRole')?.value;if(!role)return;const permissions={};document.querySelectorAll('[data-permission-resource]').forEach(el=>{const r=el.dataset.permissionResource,a=el.dataset.permissionAction;(permissions[r]||=[]);if(el.checked)permissions[r].push(a)});if(!confirm('حفظ الصلاحيات الجديدة لهذا الدور؟ ستُطبق على كل الموظفين الذين يحملون هذا الدور.'))return;try{await api('/api/admin/role-permissions',{method:'PUT',body:JSON.stringify({role,permissions})});alert('تم حفظ الصلاحيات وتطبيقها على الخادم.');await loadTab('permissions')}catch(e){alert(e.message||'تعذر حفظ الصلاحيات')}}
async function resetRolePermissions(){const role=$('#permissionRole')?.value;if(!role)return;if(!confirm('استعادة الصلاحيات الافتراضية لهذا الدور؟'))return;try{const data=await api('/api/admin/role-permissions');const defaults={};for(const r of data.resources)defaults[r.key]=[];defaults.dashboard=['view'];const base={MANAGER:{assets:['view','add','edit','delete','approve'],owners:['view','add','edit','delete','approve'],reservations:['view','add','edit','delete','approve'],offers:['view','add','edit','delete','approve'],inquiries:['view','add','edit','delete','approve'],contracts:['view','add','edit','delete','approve'],invoices:['view','add','edit','delete','approve'],categories:['view','add','edit','delete','approve'],locations:['view','add','edit','delete','approve'],conditions:['view','add','edit','delete','approve'],users:['view','add','edit'],settings:['view','add','edit'],reports:['view','add','edit'],audit:['view'],finance:['view']},SALES:{assets:['view','add','edit'],owners:['view','add','edit'],reservations:['view','add','edit'],offers:['view','add','edit'],inquiries:['view','add','edit'],contracts:['view','add','edit'],invoices:['view']},RECEPTION:{assets:['view','add'],owners:['view','add'],reservations:['view','add'],inquiries:['view','add'],conditions:['view','add'],offers:['view']},YARD:{assets:['view','add','edit'],owners:['view','add','edit'],conditions:['view','add','edit'],locations:['view','add','edit'],reservations:['view']},ACCOUNTING:{reservations:['view','add','edit','approve'],contracts:['view','add','edit','approve'],invoices:['view','add','edit','approve'],finance:['view','add','edit','approve'],reports:['view','add','edit'],assets:['view'],owners:['view'],offers:['view']}};const selected=base[role]||{};await api('/api/admin/role-permissions',{method:'PUT',body:JSON.stringify({role,permissions:{...defaults,...selected}})});await loadTab('permissions');alert('تمت استعادة الصلاحيات الافتراضية لهذا الدور.')}catch(e){alert(e.message||'تعذر استعادة الصلاحيات')}}
async function saveSettings(){if(!confirm('هل أنت متأكد من حفظ التغييرات على إعدادات النظام ومحتوى المنصة؟'))return;try{const ticker=String($('#stm')?.value||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean).slice(0,20);await api('/api/admin/settings',{method:'PUT',body:JSON.stringify({name:$('#sn').value,yardName:$('#syn')?.value||'حوش أبو مناحي',yardAddress:$('#sya')?.value||'',yardPhone:$('#syp')?.value||'',yardWhatsapp:$('#syw')?.value||'',yardEmail:$('#sye')?.value||'',yardLogo:$('#syl')?.value||'',tagline:$('#st').value,country:$('#sco').value,city:$('#sci').value,countryCode:$('#scc').value,whatsapp:$('#sw').value,phone:$('#sp').value,email:$('#se').value,address:$('#sa').value,latitude:$('#sla')?.value||'',longitude:$('#slo')?.value||'',mapsUrl:$('#smu')?.value||'',currency:$('#sc').value,storageDefaultRate:$('#sr').value,ownerName:$('#son')?.value||'أبو مناحي السبيعي',ownerPhone:$('#sop')?.value||'',managerName:$('#smn')?.value||'أبو أنس الإدريسي',managerPhone:$('#smp')?.value||'',developerName:$('#sdn')?.value||'هيثم القاضي',aboutTitle:$('#sat')?.value||'عن حوشك',aboutText:$('#sab')?.value||'',servicesText:$('#ssv')?.value||'',howToText:$('#shu')?.value||'',futureText:$('#sfu')?.value||'',tickerMessages:JSON.stringify(ticker)})});state.settings=await api('/api/public/settings');alert('تم حفظ الإعدادات ومحتوى المنصة');dashboard('settings')}catch(e){alert(e.message)}}
async function report(days){const r=await api('/api/admin/reports/summary?days='+days);$('#report').innerHTML=`<div class="stats"><div class="stat">الدخل<strong>${money(r.income)}</strong></div><div class="stat">المصروف<strong>${money(r.expense)}</strong></div><div class="stat">الصافي<strong>${money(r.net)}</strong></div><div class="stat">الأصول المضافة<strong>${r.assetsAdded}</strong></div><div class="stat">الخروج<strong>${r.exits}</strong></div><div class="stat">متأخرات التخزين<strong>${money(r.storageOutstanding)}</strong></div><div class="stat">متأخرات الفواتير<strong>${money(r.invoiceOutstanding)}</strong></div><div class="stat">الإيجارات النشطة<strong>${Number(r.activeRentals||0)}</strong></div><div class="stat">الإيجارات المتأخرة<strong>${Number(r.overdueRentals||0)}</strong></div></div><div class="field-section"><h4>الأصول حسب التصنيف</h4>${Object.entries(r.byCategory||{}).map(([k,v])=>`<div class="audit-item"><strong>${esc(k)}</strong><span>${v} أصل</span></div>`).join('')||'<div class="muted">لا توجد بيانات.</div>'}</div>`}
async function myAssets(){const xs=await api('/api/my/assets');document.querySelector('#app').innerHTML=shell(`<main class="container"><div class="panel"><h2>أصولي</h2>${xs.length?`<table><tr><th>الأصل</th><th>الكود</th><th>الغرض</th><th>الحالة</th><th>التخزين</th></tr>${xs.map(a=>`<tr><td>${esc(a.title)}</td><td>${a.code}</td><td>${purposeName(a.purpose)}</td><td>${statusName(a.status)}</td><td>${a.storage?.current?money(a.storage.current):'-'}</td></tr>`).join('')}</table>`:'<div class="empty">لا توجد أصول مرتبطة بحسابك.</div>'}</div></main>`)}
async function reply(id){const b=prompt('اكتب الرد');if(b&&b.trim()){await api('/api/admin/inquiries/'+id+'/messages',{method:'POST',body:JSON.stringify({body:b.trim()})});dashboard('inquiries')}}
async function inquiryStatus(id,status){const labels={OPEN:'إعادة الاستفسار إلى الانتظار',IN_PROGRESS:'بدء متابعة الاستفسار',CLOSED:'إغلاق الاستفسار'};const note=prompt(`سبب الإجراء: ${labels[status]||status}`);if(note===null)return;if(note.trim().length<3){alert('اكتب سببًا مختصرًا لا يقل عن 3 أحرف');return}try{await api('/api/admin/inquiries/'+id+'/status',{method:'PUT',body:JSON.stringify({status,note:note.trim()})});await dashboard('inquiries')}catch(e){alert(e.message)}}
async function exportDb(){const d=await api('/api/admin/export');if(!d?.manifest?.sha256||!d?.data)throw Error('تعذر التحقق من سلامة ملف النسخة الاحتياطية');const blob=new Blob([JSON.stringify(d,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`houshak-backup-${d.version}-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);alert(`تم تجهيز نسخة احتياطية قابلة للتحقق.
الإصدار: ${d.version}
عدد السجلات: ${Object.values(d.manifest.collectionCounts).reduce((n,x)=>n+x,0)}
SHA-256: ${d.manifest.sha256}
احتفظ بالملف في مكان آمن، واختبر الاستعادة على نسخة منفصلة قبل الاعتماد عليه.`)}
(async()=>{try{await init()}catch(e){document.querySelector('#app').innerHTML=`<div class="container"><div class="notice">${esc(e.message)}</div></div>`}})();
